function fail(m) { throw Error(m); }
function abs(u, base) { u=String(u||'').trim();if(/^[A-Za-z][A-Za-z0-9+.-]*:/.test(u)&&!/^https?:/i.test(u)||u.charAt(0)==='#')return '';return xx.resolve(base || env.baseUrl + '/', u); }
function origin(u) { var m=String(u).match(/^https?:\/\/[^/]+/i);return m?m[0]:''; }
function path(u) { return String(u).replace(/^https?:\/\/[^/]+/i, '').split(/[?#]/)[0] || '/'; }
function file(u) { return String(u).replace(/^https?:\/\/[^/]+/i, '').split('#')[0] || '/'; }
function own(u) { if(!u)return false;try{var o=origin(abs(u));return !!o&&o.toLowerCase() === origin(env.baseUrl).toLowerCase();}catch(e){return false;} }
function sameSite(u,b){var host=match(u,/^https?:\/\/([^/:]+)/).toLowerCase(),root=match(b,/^https?:\/\/([^/:]+)/).toLowerCase();return !!host&&!!root&&(host===root||host.slice(-root.length-1)==='.'+root);}
function match(s, r, index) { var a = String(s || '').match(r); return a ? (a[index || 1] || '') : ''; }
function enc(s) { return encodeURIComponent(s == null ? '' : String(s)); }
function val(o,k,d) { var v=o && o[k]; return v == null || v === '' || v === 'all' ? (d || '') : String(v); }
function firstValue(o, keys) { for (var n=0;n<keys.length;n++) if (o && o[keys[n]] != null && String(o[keys[n]]) !== '' && String(o[keys[n]]) !== 'null') return String(o[keys[n]]); return ''; }
function q(h,s,b) { return s ? xx.select(h,s,b || env.baseUrl + '/') : []; }
function one(h,s,b) { var a=q(h,s,b); return a.length ? a[0] : null; }
function text(h,s,b) { var a=one(h,s,b); return a ? a.text.trim() : ''; }
