function image(e) { var a=e && e.attrs || {}, k=['data-page-image-url','data-original','data-src','data-url','src']; for(var n=0;n<k.length;n++) if(a[k[n]] && a[k[n]].indexOf('data:')!==0)return a[k[n]];return ''; }
function plain(h) { h=String(h||'');return /[<&]/.test(h)?text('<span>'+h+'</span>','span'):h.replace(/\s+/g,' ').trim(); }
function unique(a, key) { var seen=Object.create(null),out=[]; for(var n=0;n<a.length;n++){var k=key?key(a[n]):a[n]; if(!seen[k]){seen[k]=true;out.push(a[n]);}}return out; }
function required(o,k) { if (!o || o[k]==null) fail('接口缺少字段：'+k);return o[k]; }
function json(r) { try { return JSON.parse(typeof r === 'string' ? r : r.body); } catch(e) { fail('站点返回了无效 JSON，请稍后重试'); } }
function request(u, method, body, headers, cookies) {
 var options={url:abs(u).split('#')[0],method:method||'GET',headers:headers||{}};if(P.legacy&&!options.headers['User-Agent'])options.headers['User-Agent']=P.adapter==='xinmanhua'?'okhttp/3.10.0':P.adapter==='dingmanhua'?'Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:10.0) Gecko/20100101 Firefox/10.0':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';if(!options.headers.Referer&&P.config&&P.config.referer)options.headers.Referer=P.config.referer;
 if(P.adapter==='copy4000'&&!options.headers.Accept)options.headers.Accept='application/json, text/html;q=0.9, */*;q=0.8';if(P.id==='mangabz')options.headers['User-Agent']=/^\/\d+bz\/$/.test(path(options.url))?'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0.0.0 Safari/537.36':'Mozilla/5.0 (Linux; Android 10) AppleWebKit/537.36 Chrome/120.0 Mobile Safari/537.36';if(body!=null)options.body=body;if(cookies){options.cookies=cookies;if(P.adapter==='manwa')options.persistCookies=false;}if(P.charset)options.charset=P.charset;if(P.browser&&options.method==='GET'&&sameSite(options.url,env.baseUrl))options.browser=true;
 var r=xx.request(options);if(r.error)fail(r.error);
 if(r.status<200||r.status>=300)fail('站点请求失败 HTTP '+r.status);
 if(/cf-chl-|Just a moment\.\.\./i.test(r.body))fail('站点需要验证，当前请求未取得正文');return r;
}
function get(u,referer) { return request(u,'GET',null,referer?{Referer:referer}:{}); }
function post(u,body,referer,extra) { var h={'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8',Referer:referer||env.baseUrl+'/'};Object.keys(extra||{}).forEach(function(k){h[k]=extra[k];});return request(u,'POST',body,h); }
function group(key,label,pairs,mutex) { var a=[];for(var n=0;n<pairs.length;n+=2)a.push({label:pairs[n],value:String(pairs[n+1])});var g={key:key,label:label,options:a};if(mutex)g.exclusiveGroup=String(mutex);return g; }
function slots(rows) { for(var n=0;n<rows.length;n++)rows[n].order=n;return rows; }
function dedupeLast(a, key) { var seen=Object.create(null),out=[];for(var n=a.length-1;n>=0;n--){var k=key?key(a[n]):a[n];if(!seen[k]){seen[k]=true;out.push(a[n]);}}return out.reverse(); }
function cnNum(s) { s=String(s||'').trim();if(!s)return -1;var d={'零':0,'〇':0,'一':1,'壹':1,'二':2,'贰':2,'两':2,'兩':2,'三':3,'叁':3,'四':4,'肆':4,'五':5,'伍':5,'六':6,'陆':6,'七':7,'柒':7,'八':8,'捌':8,'九':9,'玖':9},u={'十':10,'拾':10,'百':100,'佰':100,'千':1000,'仟':1000,'万':10000,'萬':10000},tot=0,sec=0,num=0,saw=false,lu=0;for(var i=0;i<s.length;i++){var c=s.charAt(i);if(d[c]!==undefined){num=d[c];saw=true;}else if(u[c]!==undefined){var v=u[c];saw=true;if(v===10000){sec=(sec+num)*v;tot+=sec;sec=0;}else{if(num===0&&v===10&&i===0)num=1;sec+=num*v;}num=0;lu=v;}else{return -1;}}if(!saw)return -1;if(num>0&&lu>=100&&s.charAt(s.length-2)!=='零'&&s.charAt(s.length-2)!=='〇'){sec+=num*(lu/10);num=0;}return tot+sec+num; }
function cleanNumText(t) { return plain(t).replace(/(?:19|20)\d{2}\s*年(?:\s*\d{1,2}\s*月(?:\s*\d{1,2}\s*[日号])?)?/g,' ').replace(/(?:^|[\s(\[【（])(?:19|20)\d{2}[-/.]\d{1,2}(?:[-/.]\d{1,2})?(?=\s|$|[)\]】）])/g,' '); }
function chNumeric(t) { var s=cleanNumText(t),m=s.match(/(?:第\s*)?(\d+(?:\.\d+)?)\s*[话話回集章期节節]/);if(m)return Number(m[1]);m=s.match(/(?:^|[\s\[\(【（])(?:ch(?:apter)?|ep(?:isode)?)\.?\s*(\d+(?:\.\d+)?)(?=\b|\D|$)/i);if(m)return Number(m[1]);m=s.match(/(?:第\s*)?([零〇一二两兩三四五六七八九十百千万萬壹贰叁肆伍陆柒捌玖拾佰仟]+)\s*[话話回集章期节節]/);if(m){var c=cnNum(m[1]);if(c>=0)return c;}if(!/[卷巻]|\bvol(?:ume)?\.?\s*\d/i.test(s)){m=s.match(/^\s*[#【\[\(（]?\s*(\d+(?:\.\d+)?)(?=\s*[-–—._:：\s\)】\]]|$)/);if(m){var v=Number(m[1]);if(!(v>=1900&&v<=2099&&m[1].indexOf('.')<0))return v;}}return -1; }
function volNumeric(t) { var s=cleanNumText(t),m=s.match(/(?:第\s*)?(\d+(?:\.\d+)?)\s*[卷巻册冊篇]/);if(m)return Number(m[1]);m=s.match(/(?:^|\b)vol(?:ume)?\.?\s*(\d+(?:\.\d+)?)(?=\b|\D|$)/i);if(m)return Number(m[1]);m=s.match(/(?:第\s*)?([零〇一二两兩三四五六七八九十百千万萬壹贰叁肆伍陆柒捌玖拾佰仟]+)\s*[卷巻册冊篇]/);if(m){var c=cnNum(m[1]);if(c>=0)return c;}return -1; }
function numeric(t) { var c=chNumeric(t);return c>=0?c:volNumeric(t); }
function ordered(rows, reverse) {
  var i,k,last=Object.create(null),tailDup=0,seen=Object.create(null),clean=[];
  for(i=0;i<rows.length;i++)last[rows[i].id]=i;
  for(i=3;i<rows.length&&i<10;i++){if(last[rows[i].id]>i)tailDup++;}
  if(tailDup>=2){rows=unique(rows,function(c){return c.id;});}
  else{for(i=0;i<rows.length;i++){k=rows[i].id;if(i<3&&last[k]>i)continue;if(!seen[k]){seen[k]=true;clean.push(rows[i]);}}rows=clean;}
  if(!rows.length)fail('没有取得本书可读章节');
  var fn=chNumeric,useVol=false,vals=[],nums=[],v;
  for(i=0;i<rows.length;i++){v=fn(rows[i].title);nums.push(v);if(v>=0)vals.push(v);}
  if(vals.length<2){useVol=true;fn=volNumeric;vals=[];nums=[];for(i=0;i<rows.length;i++){v=fn(rows[i].title);nums.push(v);if(v>=0)vals.push(v);}}
  if(vals.length<2){if(reverse)rows.reverse();return slots(rows);}
  var asc=0,desc=0;
  for(i=1;i<vals.length;i++){if(vals[i]>vals[i-1])asc++;else if(vals[i]<vals[i-1])desc++;}
  if(desc>asc){rows.reverse();}
  else if(desc===asc&&vals.length>=2){
    var half=Math.floor(vals.length/2),h1=vals.slice(0,half).sort(function(a,b){return a-b;}),h2=vals.slice(vals.length-half).sort(function(a,b){return a-b;});
    if(h1[Math.floor(h1.length/2)]>h2[Math.floor(h2.length/2)])rows.reverse();
  }
  if(!useVol&&rows.length>=4){
    vals=[];for(i=0;i<rows.length;i++){v=chNumeric(rows[i].title);if(v>=0)vals.push(v);}
    asc=0;desc=0;for(i=1;i<vals.length;i++){if(vals[i]>vals[i-1])asc++;else if(vals[i]<vals[i-1])desc++;}
    if(asc>=3&&asc>=desc*3){
      for(var h=Math.min(2,rows.length-4);h>=0;h--){
        v=chNumeric(rows[h].title);
        if(v<0||/[卷巻]/.test(rows[h].title))continue;
        var tailMax=-1,nextValid=-1;
        for(var j=h+1;j<rows.length;j++){var nv=chNumeric(rows[j].title);if(nv>=0){if(nextValid<0)nextValid=nv;if(nv>tailMax)tailMax=nv;}}
