  if(tailDup>=2){rows=unique(rows,function(c){return c.id;});}
  else{for(i=0;i<rows.length;i++){k=rows[i].id;if(i<3&&last[k]>i)continue;if(!seen[k]){seen[k]=true;clean.push(rows[i]);}}rows=clean;}
