  }
  if(!useVol&&rows.length>=4){
    vals=[];for(i=0;i<rows.length;i++){v=chNumeric(rows[i].title);if(v>=0)vals.push(v);}
    asc=0;desc=0;for(i=1;i<vals.length;i++){if(vals[i]>vals[i-1])asc++;else if(vals[i]<vals[i-1])desc++;}
    if(asc>=3&&asc>=desc*3){
