  var fn=chNumeric,useVol=false,vals=[],nums=[],v;
  for(i=0;i<rows.length;i++){v=fn(rows[i].title);nums.push(v);if(v>=0)vals.push(v);}
  if(vals.length<2){useVol=true;fn=volNumeric;vals=[];nums=[];for(i=0;i<rows.length;i++){v=fn(rows[i].title);nums.push(v);if(v>=0)vals.push(v);}}
