  var asc=0,desc=0;
  for(i=1;i<vals.length;i++){if(vals[i]>vals[i-1])asc++;else if(vals[i]<vals[i-1])desc++;}
  if(desc>asc){rows.reverse();}
  else if(desc===asc&&vals.length>=2){
    var half=Math.floor(vals.length/2),h1=vals.slice(0,half).sort(function(a,b){return a-b;}),h2=vals.slice(vals.length-half).sort(function(a,b){return a-b;});
