function tenOrdered(rows,fallbackRev){
  var list=unique(rows,function(c){return c.id;}),secs=[],bySec={},i;
  for(i=0;i<list.length;i++){
    var sec=Number(list[i].section||0);
    if(!bySec[sec]){bySec[sec]=[];secs.push(sec);}
    bySec[sec].push(list[i]);
  }
  secs.sort(function(a,b){return a-b;});
  var out=[];
  for(var si=0;si<secs.length;si++){
    var arr=bySec[secs[si]],nums=[],asc=0,desc=0,prev=-1;
    for(i=0;i<arr.length;i++){
      var n=numeric(arr[i].title);
      nums.push(n);
      if(n>=0){if(prev>=0){if(n>prev)asc++;else if(n<prev)desc++;}prev=n;}
    }
    var rev=desc>asc||(asc===0&&desc===0&&fallbackRev);
    if(rev){arr.reverse();nums.reverse();}
    var mainAsc=rev?desc:asc,mainDesc=rev?asc:desc;
    if(mainAsc>=3&&mainAsc>mainDesc*2&&arr.length>=4){
      var len=arr.length,sufMax=new Array(len),runMax=-1;
      for(i=len-1;i>=0;i--){sufMax[i]=runMax;if(nums[i]>runMax)runMax=nums[i];}
      var kept=[],keptNums=[],outliers=[];
      for(i=0;i<len;i++){
        var v=nums[i],nextV=-1;
        for(var j=i+1;j<len;j++){if(nums[j]>=0){nextV=nums[j];break;}}
        if(v>=0&&nextV>=0&&v>nextV&&sufMax[i]>=v-2&&!/(?:特别|番外|外传|短篇|附赠|特典)/.test(arr[i].title)){
          outliers.push({item:arr[i],val:v});
        }else{
          kept.push(arr[i]);keptNums.push(v);
        }
      }
      if(outliers.length){
        for(var oi=0;oi<outliers.length;oi++){
          var ov=outliers[oi].val,ins=-1;
          for(var ki=0;ki<kept.length;ki++){if(keptNums[ki]>ov){ins=ki;break;}}
          if(ins>=0){kept.splice(ins,0,outliers[oi].item);keptNums.splice(ins,0,ov);}
          else{kept.push(outliers[oi].item);keptNums.push(ov);}
        }
        arr=kept;
      }
    }
    out=out.concat(arr);
  }
  return slots(out);
}
