            || ('https://tu.manwamh5.com/comic/' + cid + '.webp');
        var s = summary(cid, title, abs(cover, r.url));
        var author = text(r.body, '.comics-detail__info h2') || text(r.body, 'h2');
        if (author) s.author = author;
        var tags = q(r.body, '.comics-detail__info .tag', r.url).map(function (x) {
            return (x.text || '').trim();
        }).filter(Boolean);
        if (tags.length) {
            if (/连载|完结|下架/.test(tags[0])) s.status = tags[0];
            s.tags = unique(tags, function (x) { return x; });
        }
        var desc = text(r.body, '.comics-detail__info p, .comics-detail p');
        if (desc && !/©\s*\d{4}/.test(desc)) {
