    },

    chapters: function (id) {
        var cid = String(id || '').trim();
        if (!/^[A-Za-z0-9]+$/.test(cid)) fail('无效漫画ID');
        var r = wmGet('/comic/' + cid, P.config.referer);
        var links = q(r.body, '#chapter-items a[href^="/' + cid + '/"]', r.url);
        var usedFallback = false;
        if (!links.length) {
            usedFallback = true;
            links = q(r.body, '.l-content a[href^="/' + cid + '/"], a[href^="/' + cid + '/"]', r.url);
        }
        var rows = [];
        var seen = {};
        var seenNorm = {};
        for (var i = 0; i < links.length; i++) {
            var a = links[i];
            var chId = match(path(a.href), new RegExp('^/' + cid + '/(\\d+)'));
            var title = (a.text || '').trim();
            if (!chId || !title || seen[chId]) continue;
            seen[chId] = true;
            var norm = title.replace(/\s+/g, '').toLowerCase();
            if (seenNorm[norm]) continue;
            seenNorm[norm] = true;
            rows.push(chapter(chId, title, a.href, 0));
        }
        if (rows.length > 1) {
            var asc = 0, desc = 0, prev = NaN;
            for (var k = 0; k < rows.length; k++) {
                var n = wmChapterNum(rows[k].title);
                if (!isFinite(n)) {
                    var fn = numeric(rows[k].title);
                    if (fn >= 0) n = fn;
                }
                if (isFinite(n)) {
                    if (isFinite(prev)) {
                        if (n > prev) asc++;
                        else if (n < prev) desc++;
