    else if (/^http:\/\/image\.yqmh\.com\//i.test(s)) s = 'https://' + s.slice(7);
    else if (/^http:\/\/image\.mhxk\.com\//i.test(s)) s = 'https://image.yqmh.com/mh/' + comicId + '_3_4.jpg-noresize.webp';
