        return unique(raw.map(function(x) { return String((x && x.name) || x || '').trim(); }).filter(Boolean));
    }
    var s = String(raw || '').trim();
    if (!s) return [];
    return unique(s.split('|').map(function(part) {
        var idx = part.indexOf(',');
        return (idx >= 0 ? part.slice(idx + 1) : part).trim();
    }).filter(Boolean));
}

