function kmListUrl(sort, order, searchKey, page, size) {
    return '/api/getsortlist/?product_id=1&productname=kmh&platformname=wap'
        + '&comic_sort=' + enc(sort || '')
        + '&orderby=' + enc(order || '')
        + '&search_key=' + enc(searchKey || '')
        + '&page=' + page
        + '&size=' + (size || 30);
}

function kmParseSortList(data) {
    var box = data && data.data ? data.data : {};
    var rows = Array.isArray(box.data) ? box.data : [];
    var items = [];
    rows.forEach(function(item) {
        var cid = item && item.comic_id ? String(item.comic_id) : '';
        var title = String((item && item.comic_name) || '').trim();
        if (!/^\d{1,12}$/.test(cid) || !title) return;
        var cover = kmCover(item.cover_img, cid);
        var sub = String(item.last_chapter_name || item.comic_author || '').trim();
        items.push({
            id: cid,
            title: title,
            cover: cover,
            subtitle: sub,
            latestChapter: String(item.last_chapter_name || '').trim(),
            tags: kmTags(item.comic_type)
        });
    });
    return {
        items: unique(items, function(x) { return x.id; }),
        hasMore: rows.length > 0
    };
}

