function meta(h,key){return attr(h,'meta[property="'+key+'"],meta[name="'+key+'"]','content');}

function zymkId(value) {
    var s = String(value || '').trim().replace(/^https?:\/\/[^/]+/i, '').replace(/\/+/g, '');
    if (!/^\d+$/.test(s)) fail('知音漫客作品编号无效');
    return s;
}

function zymkCover(raw, cid) {
    var u = String(raw || '').trim();
    if (u && !/space\.gif|blank\.gif|default/i.test(u)) {
        if (/^\/\//.test(u)) return 'https:' + u;
        if (/^\//.test(u)) return abs(u);
        return u.replace(/^http:\/\//i, 'https://');
    }
    var padded = String(cid || '');
    while (padded.length < 9) padded = '0' + padded;
    if (padded.length > 9) padded = padded.slice(-9);
    return 'https://chapter-cover.yyhao.com/file/cover/'
        + padded.slice(0, 3) + '/' + padded.slice(3, 6) + '/' + padded.slice(6, 9) + '.jpg-300x400';
}

function zymkGet(url, ref) {
    var target = abs(url);
    var opts = {
        'User-Agent': P.config.ua,
        'Referer': ref || P.config.referer
    };
    var res;
    for (var attempt = 0; attempt < 3; attempt++) {
        try {
            res = request(target, 'GET', null, opts);
            return {
                url: String((res && res.url) || target),
                body: String((res && res.body) || '')
            };
        } catch (e) {
            if (attempt >= 2 || !/timed out|reset|closed|EOF|handshake|terminated|SSLException/i.test(String(e))) throw e;
        }
    }
}

function zymkParseSortHtml(res, page) {
    var body = res.body;
    var base = res.url;
    var cards = q(body, 'li.item', base);
    if (!cards.length) cards = q(body, '.comic-item', base);
    var items = [];
    for (var i = 0; i < cards.length; i++) {
        var ch = cards[i].html || '';
        var a = one(ch, '.thumbnail a[href]', base) || one(ch, 'h3.title a[href]', base) || one(ch, 'a[href]', base);
        if (!a || !a.href) continue;
        var m = String(a.href).match(/\/(\d+)\/?$/);
        if (!m) continue;
        var cid = m[1];
        var title = plain(text(ch, 'h3.title a', base) || text(ch, 'h3.title', base) || (a.attrs && a.attrs.title));
        title = title.replace(/漫画$/, '').trim();
        if (!title) continue;
        var img = one(ch, 'img', base);
        var rawCov = img ? ((img.attrs && (img.attrs['data-src'] || img.attrs['data-original'] || img.attrs.src)) || '') : '';
        var cover = zymkCover(rawCov, cid);
        var latest = plain(text(ch, 'span.chapter', base));
        var row = summary(cid, title, cover, latest);
        row.latestChapter = latest;
        items.push(row);
    }
    var deduped = unique(items, function(x) { return x.id; });
    var totalM = body.match(/data-total="(\d+)"/i);
    var total = totalM ? Number(totalM[1]) : 0;
    var p = page > 1 ? Math.floor(page) : 1;
    var hasNext = (total > 0 && p < total) || body.indexOf('_p' + (p + 1) + '.html') >= 0;
    return {
        items: deduped,
        hasMore: deduped.length > 0 && hasNext
    };
}

function zymkExtractInitBlock(html) {
    var marker = '__cr.init(';
    var idx = html.indexOf(marker);
    if (idx < 0) return '';
    var start = html.indexOf('{', idx + marker.length);
    if (start < 0) return '';
    var depth = 0;
    var inStr = '';
    var escaped = false;
    for (var i = start; i < html.length; i++) {
        var ch = html.charAt(i);
        if (inStr) {
            if (escaped) {
                escaped = false;
            } else if (ch === '\\') {
                escaped = true;
            } else if (ch === inStr) {
                inStr = '';
            }
            continue;
        }
        if (ch === '"' || ch === "'") {
            inStr = ch;
        } else if (ch === '{') {
            depth++;
        } else if (ch === '}') {
            depth--;
            if (depth === 0) return html.slice(start, i + 1);
        }
    }
    return '';
}

function zymkEncodePathUrl(relPath) {
    var clean = String(relPath || '').trim().replace(/^\/+/, '');
    if (!clean) return '';
    var full = /^https?:\/\//i.test(clean)
        ? clean.replace(/^https?:\/\/mhpic\.zymkcdn\.com/i, 'https://mhpic.yyhao.com')
        : ('https://mhpic.yyhao.com/comic/' + clean);
    return full.indexOf('%') >= 0 ? full : encodeURI(full);
}

