    search: function(keyword, page) {
        var kw = String(keyword || '').trim();
        var p = page > 1 ? Math.floor(page) : 1;
        if (!kw) return { items: [], hasMore: false };
        var res = zymkGet('/apinew/getsortlist/?key=' + enc(kw) + '&page=' + p);
        var payload = json(res);
        var pageObj = payload && payload.data && payload.data.page ? payload.data.page : {};
        var list = Array.isArray(pageObj.comic_list) ? pageObj.comic_list : [];
        var items = [];
        for (var i = 0; i < list.length; i++) {
            var row = list[i] || {};
            var cid = String(row.comic_id || '').trim();
            var title = plain(String(row.comic_name || '').trim());
            if (!cid || !title) continue;
            var cover = zymkCover('', cid);
            var latest = row.last_chapter && row.last_chapter.name ? plain(String(row.last_chapter.name)) : '';
            var item = summary(cid, title, cover, latest);
            item.latestChapter = latest;
            if (row.comic_feature) item.description = plain(String(row.comic_feature));
            items.push(item);
        }
        items = unique(items, function(x) { return x.id; });
        var curP = Number(pageObj.current_page || p);
        var totP = Number(pageObj.total_page || 1);
        return {
            items: items,
            hasMore: items.length > 0 && curP < totP
