    },

    detail: function(id) {
        var cid = zymkId(id);
        var res = zymkGet('/' + cid + '/');
        var html = res.body;
        var title = plain(text(html, 'h1.name', res.url) || text(html, 'h1', res.url) || meta(html, 'og:novel:book_name'));
        if (!title) fail('没有找到知音漫客作品详情');
        var img = one(html, '.comic-item img', res.url);
        var rawCov = img ? ((img.attrs && (img.attrs['data-src'] || img.attrs.src)) || '') : '';
        if (!rawCov) rawCov = meta(html, 'og:image');
        var cover = zymkCover(rawCov, cid);
        var author = plain(text(html, 'span.author', res.url) || meta(html, 'og:novel:author'));
        var status = plain(meta(html, 'og:novel:status'));
        var desc = plain(meta(html, 'og:description') || text(html, '.content', res.url));
        var tags = [];
        var tLinks = q(html, '.tags-box a span, .tags-box a', res.url);
        for (var i = 0; i < tLinks.length; i++) {
            var t = plain(tLinks[i].text);
            if (t) tags.push(t);
        }
        var latest = plain(text(html, 'ul.chapterlist a.chapterBtn', res.url) || meta(html, 'og:novel:latest_chapter_name'));
        return {
            id: cid,
            title: title,
            cover: cover,
            subtitle: author || latest,
            author: author,
            status: status,
            description: desc,
            latestChapter: latest,
            tags: unique(tags)
