    },

    chapters: function(id) {
        var cid = zymkId(id);
        var res = zymkGet('/' + cid + '/');
        var html = res.body;
        var links = q(html, 'ul.chapterlist a.chapterBtn[href]', res.url);
        if (!links.length) {
            var scope = one(html, '.chapterlist-box, .comic-chapters, #chapterList, main', res.url);
            links = q(scope ? (scope.html || '') : html, 'a.chapterBtn[href]', res.url);
        }
        var out = [];
        for (var i = 0; i < links.length; i++) {
            var lk = links[i];
            var href = String(lk.href || '').trim();
            var m = href.match(/(\d+)\.html/i);
            var chId = m ? m[1] : String(i + 1);
            var chTitle = plain((lk.attrs && lk.attrs.title) || lk.text);
            if (!chTitle) continue;
            if (/付费(?:通知|公告|提示|说明)|VIP(?:通知|公告|提示)/i.test(chTitle)) continue;
            out.push(chapter(chId, chTitle, abs(href, res.url), 0));
        }
        if (!out.length) fail('没有找到知音漫客免费章节目录');
        out = unique(out, function(c) { return c.id; });
        var asc = 0, desc = 0, prev = -1;
        for (var j = 0; j < out.length; j++) {
            var n = numeric(out[j].title);
            if (n >= 0) {
                if (prev >= 0) {
                    if (n > prev) asc++;
                    else if (n < prev) desc++;
                }
                prev = n;
            }
        }
        if (desc > asc || (asc === 0 && desc === 0)) out.reverse();
        return slots(out);
    },

    chapter: function(url) {
        var target = abs(url);
        if (!own(target)) fail('章节地址不受支持');
        var res = zymkGet(target);
        var html = res.body;
        var initBlock = zymkExtractInitBlock(html);
        if (!initBlock) fail('没有找到知音漫客章节配置');

        var startM = initBlock.match(/start_var\s*:\s*(\d+)/);
        var endM = initBlock.match(/end_var\s*:\s*(\d+)/);
        var chIdM = initBlock.match(/chapter_id\s*:\s*(\d+)/);
        var highM = initBlock.match(/high\s*:\s*['"]([^'"]+)['"]/);
        var drM = initBlock.match(/dr_original\s*:\s*['"]([^'"]+)['"]/);
        var addrM = initBlock.match(/chapter_addr\s*:\s*['"]([^'"]+)['"]/);
        var sufM = initBlock.match(/image_suffix\s*:\s*['"]([^'"]+)['"]/);

        var startVar = startM ? Number(startM[1]) : 1;
        var endVar = endM ? Number(endM[1]) : 0;
        var suffix = (sufM && sufM[1]) ? sufM[1] : '.jpg';
        if (endVar < startVar || endVar <= 0) fail('知音漫客章节页数无效');

        var list = [];
        var highPattern = highM ? highM[1] : '';
        var drOriginal = drM ? drM[1] : '';
        if (!highPattern && !drOriginal && addrM && addrM[1] && chIdM) {
            var chNum = Number(chIdM[1]);
            var shift = chNum % 10;
            var encAddr = addrM[1];
            var decChars = [];
            for (var k = 0; k < encAddr.length; k++) {
                decChars.push(String.fromCharCode(encAddr.charCodeAt(k) - shift));
            }
            drOriginal = decChars.join('');
        }

        for (var p = startVar; p <= endVar; p++) {
            var rel = '';
            if (highPattern && highPattern.indexOf('$$') >= 0) {
                rel = highPattern.replace('$$', String(p));
            } else if (drOriginal) {
                rel = drOriginal + String(p) + suffix + '-zymk.high.webp';
            }
            var imgUrl = zymkEncodePathUrl(rel);
            if (imgUrl) {
                list.push({
                    url: imgUrl,
                    referer: res.url
                });
            }
        }
        if (!list.length) fail('没有读取到知音漫客章节图片');
        var chTitle = plain(text(html, 'h1', res.url) || text(html, 'title', res.url));
        return {
            title: chTitle,
            images: list
        };
    }
};

