function fcUnescape(s) {
    return String(s || '')
        .replace(/\\\//g, '/')
        .replace(/\\u([0-9a-fA-F]{4})/g, function(_, h) {
            return String.fromCharCode(parseInt(h, 16));
        })
        .replace(/\\x([0-9a-fA-F]{2})/g, function(_, h) {
            return String.fromCharCode(parseInt(h, 16));
        })
        .replace(/\\(['"\\])/g, '$1');
}

function fcId(value) {
    var s = String(value || '').trim().replace(/^\/comic\//i, '').replace(/\.html$/i, '').replace(/\/+$/, '');
    if (!/^[A-Za-z0-9]{4,24}$/.test(s)) fail('风车漫画作品编号无效');
    return s;
}

function fcImg(raw) {
    var u = String(raw || '').trim();
    if (!u || /space\.gif|blank\.gif|loading\.gif/i.test(u)) return '';
    if (/^\/\//.test(u)) return 'https:' + u;
    if (/^\//.test(u)) return abs(u);
    if (/^http:\/\/www\.fengchemh\.com\//i.test(u)) return 'https://' + u.slice(7);
    return u;
}

function fcHtml(url, ref) {
