function fcParseList(html, page) {
    var body = String(html || '');
    var cut = body.indexOf('module-items');
    if (cut < 0) cut = body.indexOf('<ul class="row">');
    var slice = cut >= 0 ? body.slice(cut) : body;
    var items = [];
    var liRe = /<li[^>]*>([\s\S]*?)<\/li>/gi;
    var m;
    while ((m = liRe.exec(slice))) {
        var block = m[1];
        var linkM = block.match(/href="\/comic\/([A-Za-z0-9]+)"/i);
        if (!linkM) continue;
        var cid = linkM[1];
        var titleM = block.match(/title="([^"]+)"/i) || block.match(/<h3[^>]*>[\s\S]*?<a[^>]*>([^<]+)<\/a>/i);
        var title = plain((titleM && titleM[1]) || '');
        if (!cid || !title) continue;
        var covM = block.match(/data-original="([^"]+)"/i)
            || block.match(/data-background="([^"]+)"/i)
            || block.match(/src="([^"]+)"/i);
        var cover = fcImg((covM && covM[1]) || '');
        var noteM = block.match(/class="[^"]*(?:note|remarks|chapter|status)[^"]*"[^>]*>([\s\S]*?)<\/[^>]+>/i);
        var latest = plain((noteM && noteM[1]) || '');
        items.push({
            id: cid,
            title: title,
            cover: cover,
            subtitle: latest,
            latestChapter: latest,
            tags: []
        });
    }
    var deduped = unique(items, function(x) { return x.id; });
    var hasNext = body.indexOf('/page/' + (page + 1)) >= 0 || deduped.length >= 24;
    return {
        items: deduped,
        hasMore: deduped.length > 0 && hasNext
    };
}

function fcNormKey(t) {
