            var nk = fcNormKey(list[i].title);
            if (nk && uniqK[nk]) continue;
            if (nk) uniqK[nk] = true;
            var cn = fcChNum(list[i].title), an = fcAltNum(list[i].title);
            if (!isNaN(cn) && isNaN(an)) nSet[String(cn)] = true;
            dedup.push({ item: list[i], cn: cn, an: an, idx: i });
        }
        var cleaned = [], lastSort = -0.5;
        for (i = 0; i < dedup.length; i++) {
