    if (/^\/\//.test(u)) return 'https:' + u;
    if (/^\//.test(u)) return abs(u, baseUrl || P.config.baseUrl);
    if (/^http:\/\/www\.manhuaba\.com\//i.test(u)) return 'https://' + u.slice(7);
    return u;
