function mhbaHtml(url, ref) {
    var target = abs(url);
    var lastErr = null;
    for (var attempt = 0; attempt < 3; attempt++) {
        try {
            var res = request(target, 'GET', null, {
                'User-Agent': P.config.ua,
                'Referer': ref || P.config.referer
            });
            return {
                url: String((res && res.url) || target),
                body: String((res && res.body) || '')
