        } catch (err) {
            lastErr = err;
            var msg = String((err && err.message) || err || '');
            if (attempt < 2 && /timed?\s*out|timeout|reset|closed|eof|handshake|terminated|ssl|connect|refused|broken pipe|HTTP 50[0234]|HTTP 429/i.test(msg)) {
                continue;
            }
            throw err;
        }
    }
    throw lastErr;
}

function mhbaUpgrade325784(url) {
