function mhbaParseList(res, page) {
    var body = String((res && res.body) || '');
    var base = String((res && res.url) || P.config.baseUrl);
    var cut = body.indexOf('module-items');
    var slice = cut >= 0 ? body.slice(cut) : body;
    var cards = q(slice, 'a.module-poster-item[href*="/comic/"]', base);
    if (!cards.length) cards = q(slice, 'a[href*="/comic/"]', base);
    var items = [];
    for (var i = 0; i < cards.length; i++) {
        var card = cards[i];
        var cidM = String(card.href || '').match(/\/comic\/([A-Za-z0-9]+)/i);
        if (!cidM) continue;
        var cid = cidM[1];
        var title = plain(text(card.html || '', '.module-poster-item-title', base)
            || (card.attrs && card.attrs.title)
            || attr(card.html || '', 'img', 'alt'));
        if (!title) continue;
        var imgEl = one(card.html || '', 'img', base);
        var rawCov = imgEl ? (image(imgEl) || (imgEl.attrs && (imgEl.attrs['data-original'] || imgEl.attrs.src)) || '') : '';
        var cover = mhbaImg(rawCov, base);
        var latest = plain(text(card.html || '', '.module-item-note', base));
        var row = summary(cid, title, cover, latest);
        row.latestChapter = latest;
        items.push(row);
    }
    var deduped = unique(items, function(x) { return x.id; });
    var hasNext = body.indexOf('/page/' + (page + 1)) >= 0 || deduped.length >= 24;
    return {
        items: deduped,
        hasMore: deduped.length > 0 && hasNext
    };
}

