        if (!a || !a.href) continue;
        var id = match(a.href, /\/comic\/([A-Za-z0-9]+)/);
        if (!id) continue;
        var title = text(c.html, 'p.dm-bn') || (a.attrs.title || '').replace(/漫画$/, '').trim();
        if (!title) continue;
        var cover = a.attrs['data-original'] || attr(c.html, 'img', 'data-original') || attr(c.html, 'img', 'src') || ('https://tu.manhuatuan.com/comic/' + id + '.webp');
