function mtNormalizeImages(list, host, useB64, refUrl) {
    var base = host ? String(host).replace(/\/+$/, '') : '';
    var out = [];
    for (var i = 0; i < list.length; i++) {
        var v = String(list[i] || '').trim();
        if (!v) continue;
        var imgUrl;
        if (/^https?:\/\//i.test(v)) {
            imgUrl = v;
        } else if (useB64 && base) {
            imgUrl = base + '/' + convert('base64Encode', v);
        } else {
            imgUrl = abs(v, base ? (base + '/') : refUrl);
        }
        out.push({url: imgUrl, referer: P.config.referer});
    }
    return out;
}

