    },

    search: function (keyword, page) {
        var kw = String(keyword || '').trim();
        if (!kw) return {items: [], hasMore: false};
        var p = mtPage(page);
        var u = '/search?q=' + enc(kw) + (p > 1 ? '&page=' + p : '');
        var r = mtGet(u, P.config.referer);
        var cards = q(r.body, 'ul.comic-list2 li', r.url);
        var rows = [];
        for (var i = 0; i < cards.length; i++) {
            var c = cards[i];
            var a = one(c.html, 'a[href*="/comic/"]', r.url);
            if (!a || !a.href) continue;
            var id = match(a.href, /\/comic\/([A-Za-z0-9]+)/);
            if (!id) continue;
            var title = text(c.html, 'span.tit') || (a.attrs.title || '').replace(/漫画$/, '').trim();
            if (!title) continue;
            var cover = a.attrs['data-original'] || attr(c.html, 'img', 'data-original') || attr(c.html, 'img', 'src') || '';
            var sub = text(c.html, 'p.info');
            rows.push(summary(id, title, cover ? abs(cover, r.url) : '', sub));
        }
        return {
            items: unique(rows, function (it) { return it.id; }),
            hasMore: mtHasNext(r, '.pagination a', p)
        };
    },

    detail: function (id) {
        var cid = String(id || '').trim();
        if (!/^[A-Za-z0-9]+$/.test(cid)) fail('无效漫画ID');
        var r = mtGet('/comic/' + cid, P.config.referer);
        var title = text(r.body, 'h2.comic-name') || text(r.body, '.comic-name');
        if (!title) fail('未取得作品标题');
        var cover = attr(r.body, 'img.comic-thumb', 'data-original') || attr(r.body, 'img.comic-thumb', 'src') || ('https://tu.manhuatuan.com/comic/' + cid + '.webp');
        var s = summary(cid, title, abs(cover, r.url));
        var infos = q(r.body, '.comic-info', r.url);
        for (var i = 0; i < infos.length; i++) {
            var t = infos[i].text.replace(/\s+/g, ' ').trim();
            if (/^作者/.test(t)) {
                s.author = t.replace(/^作者\s*(?:编剧[:：])?\s*/, '').trim();
            } else if (/^状态/.test(t)) {
                s.status = t.replace(/^状态\s*/, '').trim();
            }
        }
        var desc = text(r.body, '.comic-desc').replace(/^介绍\s*/, '').trim();
        if (desc) s.description = desc;
        return s;
    },

    chapters: function (id) {
        var cid = String(id || '').trim();
        if (!/^[A-Za-z0-9]+$/.test(cid)) fail('无效漫画ID');
        var r = mtGet('/comic/' + cid, P.config.referer);
        var links = q(r.body, '.comic-chapter a[href^="/chapter/"]', r.url);
        var rows = [];
        var seen = {};
        for (var i = 0; i < links.length; i++) {
            var a = links[i];
            var chId = match(a.href, /\/chapter\/([A-Za-z0-9]+)/);
            var title = (a.text || '').trim();
            if (!chId || !title || seen[chId]) continue;
            seen[chId] = true;
            rows.push(chapter(chId, title, a.href, 0));
        }
        var asc = 0, desc = 0, prev = -1;
        for (var j = 0; j < rows.length; j++) {
            var n = numeric(rows[j].title);
            if (n >= 0) {
                if (prev >= 0) {
                    if (n > prev) asc++;
                    else if (n < prev) desc++;
