        }
        var images = mtNormalizeImages(d.chapter_images, d.images_host, !!d.images_base64, r.url);
        if (!images.length) fail('章节图片解析为空');
        var title = text(r.body, 'h1, .chapter-title, title');
        return pageImages(u, images, title);
    }
};

