function dmtCards(r, p) {
    var cards = q(r.body, '.list-book-col-box li', r.url);
    var rows = [];
    for (var i = 0; i < cards.length; i++) {
        var c = cards[i];
        var a = one(c.html, 'a.list-book-col-240-icon[href*="/manhua/"], a[href*="/manhua/"]', r.url);
        if (!a || !a.href) continue;
        var id = match(path(a.href), /^\/manhua\/(\d+)\.htm$/);
        if (!id) continue;
        var title = (a.attrs.title || '').trim();
        var subRaw = text(c.html, 'a.list-book-col-240-name');
        if (!title) title = subRaw;
        if (!title) continue;
        var sub = subRaw;
        if (sub.indexOf(title) === 0) {
            sub = sub.slice(title.length).trim();
        }
