    return n < 1 ? 1 : n;
}

function gsGet(u, ref) {
    var lastErr;
    for (var i = 0; i < 2; i++) {
        try {
            return get(u, ref || P.config.referer);
        } catch (e) {
            lastErr = e;
            var msg = String(e && e.message ? e.message : e);
            if (/HTTP\s+(400|401|403|404)\b|规则执行失败|安全拦截|禁止/.test(msg)) {
                throw e;
            }
        }
    }
    throw lastErr;
}

function gsHttps(u) {
    var s = String(u || '').trim();
    if (!s) return '';
    if (s.indexOf('//') === 0) s = 'https:' + s;
    return s.replace(/^http:\/\/((?:[a-z0-9-]+\.)*(?:gamersky\.com|sinaimg\.cn))\b/i, 'https://$1');
}

function gsEncodeUrl(u) {
    return String(u || '').trim().replace(/[^\x21-\x7E]+/g, function (seg) {
        return encodeURIComponent(seg);
    });
}

function gsParseJsonp(body) {
    var txt = String(body || '').trim();
    if (!txt) return null;
    var iObj = txt.indexOf('{');
    var iArr = txt.indexOf('[');
    var start = -1;
    var endChar = '';
    if (iObj >= 0 && (iArr < 0 || iObj < iArr)) {
        start = iObj;
        endChar = '}';
    } else if (iArr >= 0) {
        start = iArr;
        endChar = ']';
    }
    if (start < 0) return null;
    var end = txt.lastIndexOf(endChar);
    if (end <= start) return null;
    return json(txt.slice(start, end + 1));
}

function gsContentId(url) {
    var p = path(url);
    var m = p.match(/^\/manhua\/content\/(\d+\/\d+)(?:_\d+)?\.shtml$/i);
    if (m) return m[1];
    var h = p.match(/^\/manhua\/all\/(\d+)\/?$/i);
    if (h) return 'all/' + h[1];
    return '';
}

function gsContentUrl(id) {
    var s = String(id || '').trim().replace(/^\/+/, '');
    if (/^https?:\/\//i.test(s)) return gsHttps(s);
    if (s.indexOf('all/') === 0) {
        return P.config.baseUrl + '/manhua/all/' + s.slice(4).replace(/\/+$/, '') + '/';
    }
    s = s.replace(/^manhua\/content\//, '').replace(/\.shtml$/i, '');
    return P.config.baseUrl + '/manhua/content/' + s + '.shtml';
}

function gsParseCards(html, selector, baseUrl) {
    var links = q(html, selector, baseUrl);
    var rows = [];
    var seen = {};
    for (var i = 0; i < links.length; i++) {
        var a = links[i];
        var cid = gsContentId(a.href);
        if (!cid || seen[cid]) continue;
        seen[cid] = true;
        var title = text(a.html, '.tit') || (a.attrs.title || '').trim() || (a.text || '').trim();
        if (!title) continue;
        var im = one(a.html, 'img', baseUrl);
        var cover = im ? gsEncodeUrl(gsHttps(image(im))) : '';
        var sub = text(a.html, '.time');
        rows.push(summary(cid, title, cover, sub));
    }
    return rows;
}

function gsFetchTemplate(templateKey, idNum, page) {
    var payload = JSON.stringify({
        isCache: true,
        cacheTime: 60,
        templateKey: templateKey,
        id: Number(idNum),
        page: page
    });
    var u = P.config.apiBase + '/TemplateJsonp.aspx?callback=jQuery&jsondata=' + enc(payload);
    var r = gsGet(u, P.config.referer);
    var d = gsParseJsonp(r.body);
    if (!d || typeof d !== 'object') fail('动漫星空列表解析失败');
    var html = String(d.body || '');
    var rows = gsParseCards(html, 'a[href*="/manhua/content/"]', P.config.baseUrl + '/');
    var totalPages = Number(d.totalPages || 0);
    return {
        items: rows,
        hasMore: totalPages > 0 ? page < totalPages : rows.length >= 20
    };
}

function gsFetchList(tag, page) {
    var cleanTag = String(tag || '').trim();
    if (cleanTag === 'all') cleanTag = '';
    if (page <= 2) {
        var pageUrl = P.config.baseUrl + '/manhua/' + (cleanTag ? encodeURIComponent(cleanTag) + '/' : '');
        var r = gsGet(pageUrl, P.config.referer);
        var allRows = gsParseCards(r.body, '.pageContainerData a[href*="/manhua/content/"]', r.url);
        if (allRows.length) {
            var perPage = 20;
            var start = (page - 1) * perPage;
            var slice = allRows.slice(start, start + perPage);
            if (!slice.length) return {items: [], hasMore: false};
            var more = page === 1 ? allRows.length > perPage : allRows.length >= 40;
            return {items: slice, hasMore: more};
        }
    }
    if (!cleanTag) return gsFetchTemplate('IndexPage', 20837, page);
    return gsFetchTemplate('AnimePageTag', Number(cleanTag), page);
}

function gsExtractPageImages(html, pageUrl, out, seen) {
    var imgs = q(html, '.comic-contain img', pageUrl);
    if (!imgs.length) imgs = q(html, '.Mid2L_con .picact, .Mid2L_con img', pageUrl);
    for (var i = 0; i < imgs.length; i++) {
        var raw = image(imgs[i]);
        if (!raw) continue;
        var u = gsEncodeUrl(gsHttps(abs(raw, pageUrl)));
        if (!u || seen[u]) continue;
        if (/\/(?:images|img)\/.*\.(?:gif|png)$/i.test(u) || /(?:space|grey|loading|blank|placeholder)\.gif/i.test(u)) continue;
        seen[u] = true;
        var ref = /sinaimg\.cn/i.test(u) ? 'https://weibo.com/' : P.config.referer;
        out.push({url: u, referer: ref});
    }
}

