        if (!title) fail('未取得作品标题');

        if (!cover) {
            var imgs = q(r.body, '.comic-contain img, .Mid2L_con img', r.url);
            for (var j = 0; j < imgs.length; j++) {
                var cand = gsEncodeUrl(gsHttps(abs(image(imgs[j]), r.url)));
                if (cand && /gamersky\.com/i.test(cand)) {
                    cover = cand;
                    break;
                }
            }
        }

        var s = summary(cid, title, cover);
        if (author) s.author = author;
        if (desc) s.description = desc;
        return s;
    },

    chapters: function (id) {
        var cid = String(id || '').trim();
        var artUrl = gsContentUrl(cid);
        var gid = '';
        var r = null;
        var hm = cid.match(/^all\/(\d+)$/);
        if (hm) {
            gid = hm[1];
        } else {
            r = gsGet(artUrl, P.config.referer);
            var hubLink = one(r.body, '.nav a[href*="/manhua/all/"], a[href*="/manhua/all/"]', r.url);
            if (hubLink && hubLink.href) {
                var gm = path(hubLink.href).match(/^\/manhua\/all\/(\d+)\/?$/);
                if (gm) gid = gm[1];
            }
        }

        var rows = [];
        var seen = {};
        if (gid) {
            var payload = JSON.stringify({type: 'getcontentacg', GeneralId: Number(gid), cachetime: 300});
            var ajaxUrl = P.config.apiBase + '/ContentAjaxNew.aspx?jsondata=' + enc(payload);
            var ar = gsGet(ajaxUrl, P.config.referer);
