            if (Array.isArray(list) && list.length) {
                for (var i = 0; i < list.length; i++) {
                    var item = list[i] || {};
                    var u = gsHttps(abs(item.Path || '', P.config.baseUrl + '/'));
                    var chId = gsContentId(u) || String(i + 1);
                    var chName = String(item.Subheading || item.Title || '').trim();
                    if (!u || !chName || seen[chId]) continue;
                    seen[chId] = true;
                    rows.push(chapter(chId, chName, u));
                }
            }
        }

        if (!rows.length && r) {
            var links = q(r.body, '.Mid2L_con a[href*="/manhua/content/"]', r.url);
            for (var j = 0; j < links.length; j++) {
                var a = links[j];
                var u2 = gsHttps(a.href);
                var c2 = gsContentId(u2);
                var n2 = (a.text || '').trim();
                if (!c2 || !n2 || seen[c2]) continue;
                seen[c2] = true;
                rows.push(chapter(c2, n2, u2));
            }
        }

        if (!rows.length) {
            var fallbackTitle = r ? (text(r.body, '.nav span + *') || text(r.body, 'title').replace(/[_-]\s*动漫星空.*$/i, '').trim() || '正文') : '正文';
            rows.push(chapter(cid, fallbackTitle, artUrl));
        }

        var asc = 0, desc = 0, prev = -1;
        for (var k = 0; k < rows.length; k++) {
            var n = numeric(rows[k].title);
            if (n >= 0) {
                if (prev >= 0) {
                    if (n > prev) asc++;
                    else if (n < prev) desc++;
                }
                prev = n;
            }
        }
        if (desc > asc) rows.reverse();
        return slots(rows);
    },

    chapter: function (url) {
        var u = gsHttps(abs(url, P.config.baseUrl + '/'));
        var r = gsGet(u, P.config.referer);
        var images = [];
        var imgSeen = {};
        gsExtractPageImages(r.body, r.url, images, imgSeen);

        var stemMatch = path(r.url).match(/^(\/manhua\/content\/\d+\/\d+)(?:_\d+)?\.shtml$/i);
        if (stemMatch) {
            var stem = stemMatch[1];
            var pLinks = q(r.body, '.page_css a[href]', r.url);
            var nextPages = [];
            var pSeen = {};
            for (var i = 0; i < pLinks.length; i++) {
                var pu = gsHttps(pLinks[i].href);
                var pp = path(pu);
                if (pp.indexOf(stem + '_') !== 0) continue;
                var pm = pp.match(/_(\d+)\.shtml$/i);
                if (!pm) continue;
                var num = Number(pm[1]);
                if (num <= 1 || pSeen[num]) continue;
                pSeen[num] = true;
                nextPages.push({num: num, url: pu});
            }
            nextPages.sort(function (a, b) { return a.num - b.num; });
            var maxPages = nextPages.length > 60 ? 60 : nextPages.length;
            for (var j = 0; j < maxPages; j++) {
                var pr = gsGet(nextPages[j].url, r.url);
                gsExtractPageImages(pr.body, pr.url, images, imgSeen);
            }
        }

        if (!images.length) fail('未取得章节图片');
