function fmNetPage(p) {
    var n = Math.floor(Number(p) || 1);
    return n < 1 ? 1 : n;
}

function fmNetGet(u, ref) {
    try {
        return get(u, ref);
    } catch (e) {
        return get(u, ref);
    }
}

function fmNetHasNext(r, p) {
    var links = q(r.body, 'ul.pager a, .pagination a', r.url);
    for (var i = 0; i < links.length; i++) {
        var a = links[i];
        var txt = (a.text || '').trim();
        if (txt === '下一页' || txt === '下页') return true;
        var m = (a.href || '').match(/(?:\/|[?&]page=)(\d+)(?:\.html)?$/);
        if (m && Number(m[1]) > p) return true;
    }
    return false;
}

function fmNetCards(r, p) {
    var cards = q(r.body, '.panel-recommand .media, .media', r.url);
    var rows = [];
    for (var i = 0; i < cards.length; i++) {
        var c = cards[i];
        var a = one(c.html, 'p.ph11 a[href*="/manhua/"], a[href*="/manhua/"]', r.url);
        if (!a || !a.href) continue;
        var id = match(path(a.href), /^\/manhua\/(\d+)\/?$/);
        if (!id) continue;
        var title = text(c.html, 'p.ph11 a') || (a.attrs.title || '').trim() || (a.text || '').trim();
        if (!title) continue;
        var im = one(c.html, 'img', r.url);
        var cover = im ? image(im) : '';
        var sub = text(c.html, 'p.ph12');
        rows.push(summary(id, title, cover ? abs(cover, r.url) : '', sub));
    }
    return {
        items: unique(rows, function (it) { return it.id; }),
        hasMore: fmNetHasNext(r, p)
    };
}

function fmNetRoute(filters) {
    var f = filters || {};
    var keys = ['kind', 'status', 'letter', 'sort'];
    var picked = [];
    for (var i = 0; i < keys.length; i++) {
        var v = val(f, keys[i], '');
        if (v && v !== '/manhua/' && v !== 'all') picked.push(v);
    }
    if (picked.length > 1) fail('本站仅支持单一筛选条件，请勿同时组合多个分类维度');
    return picked.length ? picked[0] : '/manhua/';
}

function fmNetEncodeUrl(u) {
    return String(u || '').trim().replace(/[^\x21-\x7E]+/g, function (seg) {
        return encodeURIComponent(seg);
    });
}

function fmNetReferer(imgUrl) {
    if (/guazicdn\.com/i.test(imgUrl)) return 'https://www.guazimanhua.com/';
    if (/hamreus\.com/i.test(imgUrl)) return 'https://www.manhuagui.com/';
    if (/dmzj\.com/i.test(imgUrl)) return 'https://www.dmzj.com/';
    return P.config.referer;
}

var source = {
    filters: function () {
        return P.filters;
    },

    latest: function (page) {
        var p = fmNetPage(page);
        var u = p > 1 ? '/manhua/' + p + '.html' : '/manhua/';
        return fmNetCards(fmNetGet(u, P.config.referer), p);
    },

    category: function (filters, page) {
        var p = fmNetPage(page);
        var route = fmNetRoute(filters);
        if (p > 1 && (route === '/rank/' || route === '/update/')) {
            return {items: [], hasMore: false};
        }
        var base = route.replace(/\/+$/, '') + '/';
        var u = p > 1 ? base + p + '.html' : base;
        return fmNetCards(fmNetGet(u, P.config.referer), p);
    },

    search: function (keyword, page) {
        var kw = String(keyword || '').trim();
        if (!kw) return {items: [], hasMore: false};
        var p = fmNetPage(page);
        var u = '/statics/search.aspx?key=' + enc(kw) + (p > 1 ? '&page=' + p : '');
        return fmNetCards(fmNetGet(u, P.config.referer), p);
    },

    detail: function (id) {
        var cid = numericId(id);
        var r = fmNetGet('/manhua/' + cid + '/', P.config.referer);
        var title = attr(r.body, 'meta[property="og:title"]', 'content') || text(r.body, 'h1');
        if (!title) fail('未取得作品标题');
        var cover = attr(r.body, 'meta[property="og:image"]', 'content') || attr(r.body, '.info img, img.img, img', 'src');
        var s = summary(cid, title.trim(), cover ? abs(cover, r.url) : '');
        var infoText = text(r.body, '.info').replace(/\s+/g, ' ').trim();
        var am = infoText.match(/作者[:：]\s*(.+?)(?:\s+更新时间|$)/);
        if (am && am[1]) s.author = am[1].trim();
        var desc = attr(r.body, 'meta[property="og:description"]', 'content') || text(r.body, '#intro, .intro');
        if (desc) s.description = desc.trim();
        return s;
    },

    chapters: function (id) {
        var cid = numericId(id);
        var r = fmNetGet('/manhua/' + cid + '/', P.config.referer);
        var links = q(r.body, '#play_0 a[href]', r.url);
        var rows = [];
        var seen = {};
        var re = new RegExp('^/manhua/' + cid + '/(\\d+)\\.html$');
        for (var i = 0; i < links.length; i++) {
            var a = links[i];
            var chId = match(path(a.href), re);
            var title = (a.text || '').trim();
            if (!chId || !title || seen[chId]) continue;
            seen[chId] = true;
            rows.push(chapter(chId, title, a.href));
        }
        var asc = 0, desc = 0, prev = -1;
        for (var j = 0; j < rows.length; j++) {
            var n = numeric(rows[j].title);
            if (n >= 0) {
                if (prev >= 0) {
                    if (n > prev) asc++;
                    else if (n < prev) desc++;
                }
                prev = n;
            }
        }
        if (desc > asc || (asc === 0 && desc === 0)) rows.reverse();
        return slots(rows);
    },

    chapter: function (url) {
        var u = abs(url, P.config.referer);
        var r = fmNetGet(u, P.config.referer);
        var raw = match(r.body, /qTcms_S_m_murl_e\s*=\s*"([^"]+)"/) || match(r.body, /qTcms_S_m_murl_e\s*=\s*'([^']+)'/);
        if (!raw) fail('未取得章节图片数据');
        var decoded = convert('base64Decode', raw);
        var parts = String(decoded || '').split('$qingtiandy$');
        var images = [];
        for (var i = 0; i < parts.length; i++) {
            var imgUrl = String(parts[i] || '').trim();
            if (!imgUrl) continue;
            imgUrl = fmNetEncodeUrl(abs(imgUrl, r.url));
            images.push({url: imgUrl, referer: fmNetReferer(imgUrl)});
        }
        if (!images.length) fail('章节图片为空');
        var title = text(r.body, 'h1, .title, title');
        return pageImages(u, images, title);
    }
