function m100Get(u, ref) {
    try {
        return get(u, ref);
    } catch (e) {
        return get(u, ref);
    }
}

function m100Unescape(s) {
    return String(s || '')
        .replace(/\\\//g, '/')
        .replace(/\\u([0-9a-fA-F]{4})/g, function (_, h) {
            return String.fromCharCode(parseInt(h, 16));
        })
        .replace(/\\x([0-9a-fA-F]{2})/g, function (_, h) {
