function m100HasNext(r, p) {
    var links = q(r.body, '.pagination a', r.url);
    for (var i = 0; i < links.length; i++) {
        var a = links[i];
        var txt = (a.text || '').trim();
        if (txt === '下一页') return true;
        var m = (a.href || '').match(/(?:\/page\/|[?&]page=)(\d+)/);
        if (m && Number(m[1]) > p) return true;
    }
    return false;
}

function m100Cards(r, p) {
    var cards = q(r.body, '.comic-items .item', r.url);
    if (!cards.length) cards = q(r.body, '.item', r.url);
    var rows = [];
    for (var i = 0; i < cards.length; i++) {
        var c = cards[i];
        var a = one(c.html, 'a.main[href]', r.url);
        if (!a || !a.href) continue;
        var id = match(path(a.href), /^\/(\d+)$/);
        if (!id) continue;
        var title = text(c.html, '.title') || (a.attrs.title || '').replace(/漫画$/, '').trim();
        if (!title) continue;
        var cover = attr(c.html, '.thumbnail', 'data-original') || attr(c.html, '.thumbnail', 'src') || ('https://cover.manhua100.com/cover/' + id + '.webp');
        var sub = text(c.html, '.body .row');
        rows.push(summary(id, title, abs(cover, r.url), sub));
    }
    return {
        items: unique(rows, function (it) { return it.id; }),
        hasMore: m100HasNext(r, p)
    };
}

function m100CatUrl(filters, p) {
    var segs = [P.listPrefix || '/category'];
    var keys = ['area', 'theme', 'state', 'order'];
    for (var i = 0; i < keys.length; i++) {
        var k = keys[i];
        var v = val(filters, k, '');
        if (v && v !== 'all') {
            segs.push(k, enc(v));
        }
    }
    if (p > 1) segs.push('page', String(p));
    return segs.join('/');
}

function m100NormalizeImages(list, host, useB64, refUrl) {
    var base = host ? String(host).replace(/\/+$/, '') : '';
    var out = [];
    for (var i = 0; i < list.length; i++) {
        var v = String(list[i] || '').trim();
        if (!v) continue;
        var imgUrl;
        if (/^https?:\/\//i.test(v)) {
            imgUrl = v;
        } else if (useB64 && base) {
            imgUrl = base + '/' + convert('base64Encode', v);
        } else {
            imgUrl = abs(v, base ? (base + '/') : refUrl);
        }
        out.push({url: imgUrl, referer: P.config.referer});
    }
    return out;
}

