                prev = n;
            }
        }
        if (desc > asc) rows.reverse();
        var hi = -1;
        for (var k = 0; k < rows.length; k++) {
            var cur = numeric(rows[k].title);
            if (!(cur >= 0)) { hi = -1; continue; }
            if (hi >= 0 && cur < hi && (hi - cur) <= 35) {
                var pos = k;
                while (pos > 0 && (k - pos) < 40) {
                    var pn = numeric(rows[pos - 1].title);
                    if (!(pn >= 0) || pn <= cur) break;
                    var tmp = rows[pos - 1];
                    rows[pos - 1] = rows[pos];
                    rows[pos] = tmp;
                    pos--;
