  if (Array.isArray(c.authors)) {
    for (var i = 0; i < c.authors.length; i++) {
      if (c.authors[i] && c.authors[i].name) authors.push(plain(c.authors[i].name));
    }
  }
  var tags = [];
  if (Array.isArray(c.categories)) {
    for (var j = 0; j < c.categories.length; j++) {
      if (c.categories[j] && c.categories[j].name) tags.push(plain(c.categories[j].name));
    }
  }
  var item = summary(String(c.id), plain(c.title), c.imageUrl || "", authors.join(" / "));
  item.tags = unique(tags).slice(0, 64);
  if (c.lastChapterUpdate) item.latestChapter = "第" + plain(c.lastChapterUpdate) + "话";
  return item;
}

var COMIC_FIELDS = "id title status imageUrl lastChapterUpdate authors { name } categories { id name }";

var source = {
  validate: function () {
    return true;
  },
  filters: function () {
    var cached = xx.cacheGet("komiic:cats");
    var cats = null;
    if (cached) {
      try {
        cats = JSON.parse(cached);
      } catch (e) {
        cats = null;
      }
    }
    if (!cats) {
      var data = gql("allCategory", "query allCategory { allCategory { id name } }", {});
      cats = Array.isArray(data.allCategory) ? data.allCategory : [];
      if (cats.length) xx.cacheSet("komiic:cats", JSON.stringify(cats), 3600);
    }
    var catOpts = [{ label: "全部", value: "all" }];
    for (var i = 0; i < cats.length; i++) {
      var c = cats[i];
      if (!c || !c.id || !c.name) continue;
      catOpts.push({ label: plain(c.name), value: String(c.id) });
    }
    return [
      { key: "category", label: "分类", options: catOpts },
      {
        key: "status",
        label: "状态",
        options: [
          { label: "全部", value: "" },
          { label: "连载中", value: "ONGOING" },
          { label: "已完结", value: "END" }
        ]
      },
      {
        key: "order",
        label: "排序",
        options: [
          { label: "最近更新", value: "DATE_UPDATED" },
          { label: "人气最高", value: "VIEWS" },
          { label: "最新上架", value: "DATE_CREATED" }
        ]
      }
    ];
  },
  latest: function (page) {
    var p = pageNum(page);
    var q = "query recentUpdate($pagination: Pagination!) { recentUpdate(pagination: $pagination) { " + COMIC_FIELDS + " } }";
    var data = gql("recentUpdate", q, {
      pagination: { limit: PAGE_SIZE, offset: (p - 1) * PAGE_SIZE, orderBy: "DATE_UPDATED", status: "", asc: false }
    });
    var rows = Array.isArray(data.recentUpdate) ? data.recentUpdate : [];
    var items = [];
    for (var i = 0; i < rows.length; i++) {
      if (rows[i] && rows[i].id && rows[i].title) items.push(mapComic(rows[i]));
    }
    return { items: items, hasMore: rows.length >= PAGE_SIZE };
  },
  category: function (filters, page) {
    var f = filters || {};
    var p = pageNum(page);
    var pag = {
      limit: PAGE_SIZE,
      offset: (p - 1) * PAGE_SIZE,
      orderBy: f.order || "DATE_UPDATED",
      status: f.status || "",
      asc: false
    };
    var cat = f.category;
    var rows;
    if (cat && cat !== "all") {
      var q = "query comicByCategories($categoryId: [ID!]!, $pagination: Pagination!) { comicByCategories(categoryId: $categoryId, pagination: $pagination) { " + COMIC_FIELDS + " } }";
      var data = gql("comicByCategories", q, { categoryId: [String(cat)], pagination: pag });
      rows = Array.isArray(data.comicByCategories) ? data.comicByCategories : [];
    } else {
      var q2 = "query comicByCategoriesAll($pagination: Pagination!) { recentUpdate(pagination: $pagination) { " + COMIC_FIELDS + " } }";
      var data2 = gql("comicByCategoriesAll", q2, { pagination: pag });
      rows = Array.isArray(data2.recentUpdate) ? data2.recentUpdate : [];
    }
    var items = [];
    for (var i = 0; i < rows.length; i++) {
      if (rows[i] && rows[i].id && rows[i].title) items.push(mapComic(rows[i]));
    }
    return { items: items, hasMore: rows.length >= PAGE_SIZE };
  },
  search: function (keyword, page) {
    var q = plain(keyword);
    if (!q || pageNum(page) > 1) return { items: [], hasMore: false };
    var query = "query searchComicsAndAuthors($keyword: String!) { searchComicsAndAuthors(keyword: $keyword) { comics { " + COMIC_FIELDS + " } } }";
    var data = gql("searchComicsAndAuthors", query, { keyword: q });
    var rows = data.searchComicsAndAuthors && Array.isArray(data.searchComicsAndAuthors.comics)
      ? data.searchComicsAndAuthors.comics
      : [];
    var items = [];
    for (var i = 0; i < rows.length; i++) {
      if (rows[i] && rows[i].id && rows[i].title) items.push(mapComic(rows[i]));
    }
    return { items: items, hasMore: false };
  },
  detail: function (id) {
    var query = "query comicById($comicId: ID!) { comicById(comicId: $comicId) { id title status year imageUrl description lastChapterUpdate authors { name } categories { id name } } }";
    var data = gql("comicById", query, { comicId: String(id) }, abs("/comic/" + enc(id)));
    var c = data.comicById;
    if (!c) fail("Komiic 未找到作品: " + id);
    var out = mapComic(c);
    out.author = out.subtitle || "";
    out.status = c.status === "END" ? "已完结" : (c.status === "ONGOING" ? "连载中" : plain(c.status || ""));
    out.description = plain(c.description || "");
    return out;
  },
  chapters: function (id) {
    var query = "query chaptersByComicId($comicId: ID!) { chaptersByComicId(comicId: $comicId) { id serial type size dateUpdated } }";
    var data = gql("chaptersByComicId", query, { comicId: String(id) }, abs("/comic/" + enc(id)));
    var rows = Array.isArray(data.chaptersByComicId) ? data.chaptersByComicId : [];
    var chs = [], books = [];
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i];
      if (!r || !r.id) continue;
      var entry = { row: r, num: parseFloat(String(r.serial || "").replace(/[^0-9.]/g, "")), idx: i };
      if (r.type === "book") books.push(entry);
      else chs.push(entry);
    }
    function cmp(a, b) {
      if (!isNaN(a.num) && !isNaN(b.num) && a.num !== b.num) return a.num - b.num;
      return a.idx - b.idx;
    }
    chs.sort(cmp);
    books.sort(cmp);
    var out = [];
    var seen = {};
    function appendList(arr, sec, unit) {
      for (var k = 0; k < arr.length; k++) {
        var r = arr[k].row;
        var cid = String(r.id);
        if (seen[cid]) continue;
        seen[cid] = true;
        var label = "第" + plain(r.serial || String(k + 1)) + unit + (r.size ? " (" + r.size + "p)" : "");
        out.push({
          id: cid,
          title: label,
          url: abs("/comic/" + enc(id) + "/chapter/" + enc(cid) + "/images/all"),
          section: sec,
          order: out.length
        });
      }
    }
    appendList(chs, 0, "话");
    appendList(books, 1, "卷");
    return out;
  },
  chapter: function (url) {
    var m = match(url, /\/chapter\/([^\/]+)\//);
    if (!m) fail("无法解析 Komiic 章节 ID: " + url);
    var chId = decodeURIComponent(m);
    var referer = url + "?page=1";
    var query = "query imagesByChapterId($chapterId: ID!) { imagesByChapterId(chapterId: $chapterId) { id kid width height } }";
    var data = gql("imagesByChapterId", query, { chapterId: chId }, referer);
    var rows = Array.isArray(data.imagesByChapterId) ? data.imagesByChapterId : [];
    var imgs = [];
    for (var i = 0; i < rows.length; i++) {
      var it = rows[i];
      if (!it || !it.kid) continue;
      imgs.push({
        url: abs("/api/image/" + enc(it.kid)),
        referer: referer,
        headers: {
          Referer: referer,
          Accept: "image/avif,image/webp,image/apng,image/*,*/*;q=0.8"
        }
      });
    }
    if (!imgs.length) fail("章节没有可读图片: " + url);
    return {
      title: "",
      images: imgs,
      nextPageUrl: ""
    };
  }
};

