function searchManga(tagQuery, page, order, smodeOverride) {
  var p = pageNum(page);
  var ord = order || "date_d";
  var smode = smodeOverride === true ? "s_tag_full" : (smodeOverride || "s_tag");
  var u = abs("/ajax/search/manga/" + enc(tagQuery)) +
    "?word=" + enc(tagQuery) +
    "&order=" + enc(ord) +
    "&mode=all&p=" + p +
    "&s_mode=" + smode +
    "&type=manga&lang=zh";
  var body = pxGet(u);
  var manga = body && body.manga ? body.manga : null;
  var rows = manga && Array.isArray(manga.data) ? manga.data : [];
  var total = manga && manga.total ? Number(manga.total) : 0;
  var items = [];
  for (var i = 0; i < rows.length; i++) {
    var it = rows[i];
    if (!it || !it.id || !it.title || it.isAdContainer) continue;
    if (Number(it.xRestrict || 0) !== 0) continue;
    var item = summary(
      String(it.id),
      plain(it.title),
      "",
      plain(it.userName || "")
    );
    if (it.url) item.cover = pxImg(it.url);
    var tags = [];
    if (Array.isArray(it.tags)) {
      for (var t = 0; t < it.tags.length; t++) {
        var tg = plain(it.tags[t]);
        if (tg) tags.push(tg);
      }
    }
    item.tags = unique(tags).slice(0, 64);
    var pc = Number(it.pageCount || 1);
    item.latestChapter = it.seriesTitle ? plain(it.seriesTitle) : (pc + "P");
    items.push(item);
  }
  var hasMore = rows.length >= 60 && p < 10 && (total === 0 || p * 60 < total);
  return {
    items: items,
    hasMore: hasMore
  };
}

function fetchIllustMeta(id, saveDetailFields) {
  var key = "px:m:" + id;
  if (!saveDetailFields) {
    var cached = xx.cacheGet(key);
    if (cached) {
      try {
        return JSON.parse(cached);
      } catch (e) {}
    }
  }
  var b = pxGet(abs("/ajax/illust/" + enc(id) + "?lang=zh"));
  if (!b || !b.id) fail("Pixiv 未找到作品: " + id);
  if (Number(b.xRestrict || 0) !== 0) fail("跳过受限作品: " + id);
  var meta = {
    seriesId: b.seriesNavData && b.seriesNavData.seriesId ? String(b.seriesNavData.seriesId) : "",
    pageCount: Number(b.pageCount || 1)
  };
  xx.cacheSet(key, JSON.stringify(meta), 180);
  return saveDetailFields ? b : meta;
}

var source = {
  validate: function () {
    return true;
  },
  filters: function () {
    return [
      {
        key: "tag",
        label: "中文标签",
        options: [
          { label: "中文 (全部)", value: "all" },
          { label: "中国語", value: "中国語" },
          { label: "漢化", value: "漢化" },
          { label: "漫画", value: "漫画 中文" },
          { label: "日常", value: "日常 中文" },
          { label: "原创", value: "原创 中文" },
          { label: "恋爱", value: "恋爱 中文" },
          { label: "搞笑", value: "搞笑 中文" }
        ]
      },
      {
        key: "order",
        label: "排序",
        options: [
          { label: "最新", value: "date_d" },
          { label: "早期", value: "date" }
        ]
      }
    ];
  },
  latest: function (page) {
    return searchManga("中文", page, "date_d", true);
  },
  category: function (filters, page) {
    var f = filters || {};
    var tag = f.tag && f.tag !== "all" ? f.tag : "中文";
    var exact = tag.indexOf(" ") < 0;
    return searchManga(tag, page, f.order || "date_d", exact);
  },
  search: function (keyword, page) {
    var q = plain(keyword);
    if (!q) return { items: [], hasMore: false };
    var res = searchManga(q + " 中文", page, "date_d", "s_tag_tc");
    if ((!res.items || !res.items.length) && pageNum(page) === 1) {
      res = searchManga(q, page, "date_d", "s_tag_tc");
    }
    return res;
  },
  detail: function (id) {
    var b = fetchIllustMeta(id, true);
    var coverUrl = (b.urls && (b.urls.regular || b.urls.small || b.urls.thumb)) || "";
    var out = summary(
      String(id),
      plain(b.title || id),
      "",
      plain(b.userName || "")
    );
    if (coverUrl) out.cover = pxImg(coverUrl);
    out.author = plain(b.userName || "");
    out.status = b.seriesNavData ? "连载中" : "短篇";
    var desc = String(b.description || "").replace(/<br\s*\/?>/gi, "\n").replace(/<[^>]+>/g, " ");
    out.description = plain(desc);
    var tags = [];
    var tagList = b.tags && Array.isArray(b.tags.tags) ? b.tags.tags : [];
    for (var i = 0; i < tagList.length; i++) {
      if (tagList[i] && tagList[i].tag) tags.push(plain(tagList[i].tag));
    }
    out.tags = unique(tags).slice(0, 64);
    out.latestChapter = b.seriesNavData && b.seriesNavData.title
      ? plain(b.seriesNavData.title)
      : ((b.pageCount || 1) + "P");
    return out;
  },
  chapters: function (id) {
    var meta = fetchIllustMeta(id, false);
    if (meta.seriesId) {
      var sid = meta.seriesId;
      var allEntries = [];
      var titleById = {};
      var pageCountById = {};
      for (var p = 1; p <= 5; p++) {
        var sb = pxGet(abs("/ajax/series/" + enc(sid) + "?p=" + p + "&lang=zh"));
        var pageObj = sb && sb.page ? sb.page : null;
        var list = pageObj && Array.isArray(pageObj.series) ? pageObj.series : [];
        var thumbs = sb && sb.thumbnails && Array.isArray(sb.thumbnails.illust) ? sb.thumbnails.illust : [];
        for (var t = 0; t < thumbs.length; t++) {
          var th = thumbs[t];
          if (th && th.id) {
            titleById[String(th.id)] = plain(th.title || "");
            pageCountById[String(th.id)] = Number(th.pageCount || 1);
          }
        }
        for (var i = 0; i < list.length; i++) {
          if (list[i] && list[i].workId) allEntries.push(list[i]);
        }
        var total = pageObj && pageObj.total ? Number(pageObj.total) : 0;
        if (!list.length || (total > 0 && allEntries.length >= total)) break;
      }
      if (allEntries.length) {
        allEntries.sort(function (a, c) {
          return Number(a.order || 0) - Number(c.order || 0);
        });
        var out = [];
        var seen = {};
        for (var k = 0; k < allEntries.length; k++) {
          var w = allEntries[k];
          var wid = String(w.workId);
          if (seen[wid]) continue;
          seen[wid] = true;
          var label = titleById[wid] || ("第" + (w.order || (k + 1)) + "话");
          var pc = pageCountById[wid];
          if (pc) label += " (" + pc + "P)";
          out.push({
            id: wid,
            title: label,
            url: abs("/ajax/illust/" + enc(wid) + "/pages?lang=zh"),
            section: 0,
            order: out.length
          });
        }
        if (out.length) return out;
      }
    }
    var pages = Number(meta.pageCount || 1);
    return [
      {
        id: String(id),
        title: "正篇" + (pages > 1 ? " (" + pages + "P)" : ""),
        url: abs("/ajax/illust/" + enc(id) + "/pages?lang=zh"),
        section: 0,
        order: 0
      }
    ];
  },
  chapter: function (url) {
    var rows = pxGet(url);
    if (!Array.isArray(rows) || !rows.length) fail("Pixiv 章节没有图片: " + url);
    var imgs = [];
    for (var i = 0; i < rows.length; i++) {
      var u = rows[i] && rows[i].urls && (rows[i].urls.regular || rows[i].urls.original || rows[i].urls.small);
      if (u) imgs.push(pxImg(u));
    }
    if (!imgs.length) fail("Pixiv 章节图片列表为空: " + url);
    return {
      title: "",
      images: imgs,
      nextPageUrl: ""
    };
  }
};

