var KB_SITE = "https://www.kaobei.org";
var KB_HEADERS = {
  Referer: KB_SITE + "/",
  Accept: "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
  "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.8"
};

function kbHttps(url) {
  var u = String(url || "").trim();
  if (!u) return "";
  if (u.indexOf("//") === 0) return "https:" + u;
  return u.replace(/^http:\/\//i, "https://");
}

function kbGet(url, referer) {
  return request(url, "GET", null, {
    Referer: referer || KB_SITE + "/",
    Accept: KB_HEADERS.Accept,
    "Accept-Language": KB_HEADERS["Accept-Language"]
  });
}

function kbPageNum(page) {
  return Math.max(1, Number(page) || 1);
}

function kbNormId(id) {
  var s = String(id || "").trim();
  s = s.replace(/^https?:\/\/[^/]+/i, "").replace(/^\/+|\/+$/g, "");
  if (!s || !/^[A-Za-z0-9_\/-]+$/.test(s)) fail("作品标识无效: " + id);
  return s;
}

function kbCoverFromStyleOrImg(cardHtml, baseUrl) {
  var p = one(cardHtml, "p.mh-cover, .mh-cover");
  var st = p && p.attrs && p.attrs.style ? String(p.attrs.style) : "";
  var bg = match(st, /url\((['"]?)([^)'"]+)\1\)/, 2);
  if (bg) return kbHttps(abs(bg, baseUrl));
  var img = one(cardHtml, "img");
  var raw = image(img);
  return raw ? kbHttps(abs(raw, baseUrl)) : "";
}

function kbHasNextPage(r, page, isSearch) {
  var links = q(r.body, "a[href]", r.url);
  for (var i = 0; i < links.length; i++) {
    var t = plain(links[i].text);
    var href = String(links[i].href || "");
    if (t === "下一页" || t === "下页" || t === ">") {
      if (href && href.indexOf("javascript") < 0 && href !== "#") return true;
    }
    if (isSearch) {
      var sp = match(href, /[?&]page=(\d+)/);
      if (sp && Number(sp) > page) return true;
    } else {
      var lp = match(href, /\/(\d+)\.html(?:$|\?)/);
      if (lp && Number(lp) > page) return true;
    }
  }
  return false;
}

function kbParseCards(r, page, isSearch) {
  var cards = q(r.body, ".mh-item", r.url);
  var items = [];
  var seen = {};
  for (var i = 0; i < cards.length; i++) {
    var ch = cards[i].html;
    var a = one(ch, ".mh-item-detali h2.title a, h2.title a");
    if (!a || !a.href) continue;
    var p = path(a.href).replace(/^\/+|\/+$/g, "");
    if (!p || p.indexOf("/") < 0 || /\.html$/i.test(p)) continue;
    if (seen[p]) continue;
    seen[p] = true;
    var rawTitle = plain(a.text || (a.attrs && a.attrs.title));
    if (!rawTitle) continue;
    var title = plain(rawTitle.replace(/漫画$/, "")) || rawTitle;
    var cover = kbCoverFromStyleOrImg(ch, r.url);
    var latest = plain(text(ch, ".mh-item-detali p.chapter a, p.chapter a"));
    var item = summary(p, title, cover, latest);
    item.latestChapter = latest;
    items.push(item);
  }
  if (!items.length && !/没有|暂无|未找到|搜索/.test(r.body)) {
    emptyListing(r, items);
  }
  return {
    items: items,
    hasMore: items.length > 0 && kbHasNextPage(r, page, isSearch)
  };
}

