function dmParseLikeData(r) {
  var cards = q(r.body, ".likedata", r.url);
  var items = [];
  var seen = {};
  for (var i = 0; i < cards.length; i++) {
    var ch = cards[i].html;
    var a = one(ch, ".likeimg a, .likeinfo a");
    if (!a || !a.href) continue;
    var id = match(path(a.href), /^\/([A-Za-z0-9_-]+)\/?$/);
    if (!id || seen[id]) continue;
    seen[id] = true;
    var title = plain(text(ch, ".likeinfo p.le-t"));
    var imgEl = one(ch, ".likeimg img");
    if (!title && imgEl && imgEl.attrs) title = plain(imgEl.attrs.alt || imgEl.attrs.title);
    if (!title) continue;
    var cover = dmPickImg(imgEl, r.url);
    var pList = q(ch, ".likeinfo p", r.url);
    var latest = "";
    var author = "";
    for (var j = 0; j < pList.length; j++) {
      var pt = plain(pList[j].text);
      if (/^最新[：:]/.test(pt)) latest = plain(pt.replace(/^最新[：:]\s*/, ""));
      if (/^作者[：:]/.test(pt)) author = plain(pt.replace(/^作者[：:]\s*/, ""));
    }
    var item = summary(id, title, cover, latest || author);
    item.latestChapter = latest;
    items.push(item);
  }
  emptyListing(r, items);
  return { items: items, hasMore: false };
}

