    for (var i = 0; i < pool.length; i += step) samples.push(pool[i]);
    samples.sort(cmp);
    var sIdx = Math.min(samples.length - 1, Math.ceil((need * 2.5 + 40) * samples.length / pool.length));
    var cutoff = samples[sIdx][scoreIdx];
    var gt = [], eq = [];
