    for (var i = 0; i < links.length; i++) {
        var a = links[i];
        var href = a.href || '';
        var id = match(href, /\/comic\/(\d+)/);
        if (!id) continue;
        var title = plain(text(a.html, 'figcaption, .comicRwdList__item_text') || attr(a.html, 'img', 'alt') || a.text);
        if (!title) continue;
        var imgNode = one(a.html, 'img', r.url);
        var rawImg = imgNode ? image(imgNode) : '';
        var sub = text(a.html, '.comic-item-tag');
        var item = summary(id, title, '', sub);
        var desc = acgsImageDescriptor(rawImg, r.url);
        if (desc) item.cover = desc;
        rows.push(item);
    }
    var hasMore = false;
    var pgLinks = q(r.body, 'link[rel="next"], a[href*="page="]', r.url);
    var curPage = Number(match(r.url, /[?&]page=(\d+)/) || 1);
    for (var j = 0; j < pgLinks.length; j++) {
        var cand = abs(pgLinks[j].href || (pgLinks[j].attrs && pgLinks[j].attrs.href) || '', r.url);
        var pNum = Number(match(cand, /[?&]page=(\d+)/) || 0);
        if (pNum > curPage && own(cand)) {
            hasMore = true;
            break;
        }
    }
    return {
        items: unique(rows, function (it) { return it.id; }),
        hasMore: hasMore
    };
}

function acgsJsonLdObjects(html) {
    var out = [];
    var scripts = q(html, 'script[type="application/ld+json"]');
    for (var i = 0; i < scripts.length; i++) {
        var raw = (scripts[i].text || '').trim();
        if (!raw) continue;
        try {
            var parsed = JSON.parse(raw);
            if (Array.isArray(parsed)) {
                for (var j = 0; j < parsed.length; j++) out.push(parsed[j]);
            } else if (parsed && typeof parsed === 'object') {
                out.push(parsed);
            }
        } catch (ignore) {}
    }
    return out;
}

