function san421CardItems(r) {
    var cards = q(r.body, 'article.excerpt', r.url);
    var rows = [];
    for (var i = 0; i < cards.length; i++) {
        var card = cards[i];
        var catText = text(card.html, 'p.cat, header .cat');
        if (/美女|写真|图集/.test(catText)) continue;
        var link = one(card.html, 'h2 a[href*="/post/"]', r.url);
        var href = link && link.href || '';
        if (!href || /\/meinv\//i.test(href)) continue;
        var id = match(href, /\/post\/(\d+)\.html/);
        if (!id) continue;
        var rawTitle = (link.attrs && (link.attrs['data-title'] || link.attrs.title)) || link.text || '';
        var title = plain(rawTitle).replace(/-三四娱乐\s*$/, '').trim();
        if (!title) continue;
        var imgNode = one(card.html, '.focus img, a.thumbnail img, img', r.url);
        var cover = imgNode ? abs(image(imgNode), r.url) : '';
        var sub = text(card.html, 'header .subtitle, .subtitle');
        rows.push(summary(id, title, cover, sub));
    }
    var hasMore = !!next(r, '.pagination a, nav.navigation a, a[href*="/page/"]');
    return {
        items: unique(rows, function (it) { return it.id; }),
        hasMore: hasMore
    };
}

function san421ExtractPageImages(html, pageUrl) {
    var nodes = q(html, '.article-content .img-placeholder-wrap img', pageUrl);
    if (!nodes.length) nodes = q(html, '.article-content img', pageUrl);
    var out = [];
    for (var i = 0; i < nodes.length; i++) {
        var u = image(nodes[i]);
        if (!u) continue;
        var absU = abs(u, pageUrl);
        if (!absU || /placeholder\.gif|logo\.png|wap-logo\.png|\/manga-cover\//i.test(absU)) continue;
        out.push(absU);
    }
    return out;
}

var S4_CATS = [
    '全部漫画', 'all',
    '爱情漫画', '4'
];

var S4_TAGS = [
    '全部标签', 'all',
    '连载', '572',
    '完结', '568',
    '精品漫画', '569',
    '短篇漫画', '570',
    '都市', '32',
    '校园', '33'
];

var S4_SORTS = [
    '最新发布', 'all',
    '最近更新', 'modified',
    '标题升序', 'title'
];

function san421WpComics(cat, tag, ord, p) {
    var effCat = (cat && cat !== 'all') ? cat : '4';
    if (effCat !== '4') fail('分类参数无效');
    if (tag && tag !== 'all' && !/^\d+$/.test(tag)) fail('标签参数无效');
    if (ord && ord !== 'all' && ['modified', 'title'].indexOf(ord) < 0) fail('排序参数无效');
    var qs = 'per_page=20&page=' + p + '&categories=' + enc(effCat);
    if (tag && tag !== 'all') qs += '&tags=' + enc(tag);
    if (ord && ord !== 'all') qs += '&orderby=' + enc(ord) + (ord === 'title' ? '&order=asc' : '');
    qs += '&_fields=id,slug,link,title,categories,tags';
    var r = get('/wp-json/wp/v2/posts?' + qs, env.baseUrl + '/');
    var list = json(r);
    if (!Array.isArray(list)) fail('接口返回格式异常');
    var rows = [];
    for (var i = 0; i < list.length; i++) {
        var post = list[i];
        if (!post || !post.id) continue;
        var pid = String(post.id);
        var title = plain(post.title && post.title.rendered ? post.title.rendered : '').replace(/-三四娱乐\s*$/, '').trim();
        if (!title) continue;
        var cover = 'https://imgs.34img.cc/manga-cover/' + pid + '/cover.jpg';
        rows.push(summary(pid, title, cover, ''));
    }
    return {
        items: unique(rows, function (it) { return it.id; }),
        hasMore: list.length >= 20
    };
}

var source = {
    filters: function () {
        return [
            group('cat', '漫画分类', S4_CATS),
            group('tag', '题材标签', S4_TAGS),
            group('orderby', '排序', S4_SORTS)
        ];
    },

    latest: function (page) {
        var p = Math.max(1, Math.floor(Number(page) || 1));
        return san421WpComics('4', '572', 'all', p);
    },

    category: function (filters, page) {
        var p = Math.max(1, Math.floor(Number(page) || 1));
        var f = filters || {};
        var cat = val(f, 'cat', 'all');
        var tag = val(f, 'tag', 'all');
        var ord = val(f, 'orderby', 'all');
        if (tag === '%e5%ae%8c%e7%bb%93') tag = '568';
        else if (tag === '%e7%b2%be%e5%93%81%e6%bc%ab%e7%94%bb') tag = '569';
        else if (tag === '%e7%9f%ad%e7%af%87%e6%bc%ab%e7%94%bb') tag = '570';
        else if (tag === '%e9%83%bd%e5%b8%82') tag = '32';
        return san421WpComics(cat, tag, ord, p);
    },

    search: function (keyword, page) {
        var kw = String(keyword || '').trim();
        if (!kw) return {items: [], hasMore: false};
        var p = Math.max(1, Math.floor(Number(page) || 1));
        var url = (p > 1 ? '/page/' + p : '/') + '?s=' + enc(kw);
        var r = get(url, env.baseUrl + '/');
        return san421CardItems(r);
    },

    detail: function (id) {
        var pid = numericId(id);
        var r = get('/post/' + pid + '.html', env.baseUrl + '/item/%e8%bf%9e%e8%bd%bd');
        var title = text(r.body, 'h1.article-title, .article-header h1, h1').replace(/-三四娱乐\s*$/, '').trim();
        if (!title) fail('未取得作品标题');
        var cover = meta(r.body, 'og:image');
        if (!cover) {
            var imgs = q(r.body, '.article-content img', r.url);
            for (var i = 0; i < imgs.length; i++) {
                var u = abs(image(imgs[i]), r.url);
                if (u && /\/manga-cover\//i.test(u)) {
                    cover = u;
                    break;
                }
            }
        }
        if (!cover) cover = 'https://imgs.34img.cc/manga-cover/' + pid + '/cover.jpg';
        var tags = [];
        var tagEls = q(r.body, '.article-tags a, .post-tags a');
        for (var j = 0; j < tagEls.length; j++) {
            var tt = tagEls[j].text.trim();
            if (tt && tags.length < 24) tags.push(tt);
        }
        var chEls = q(r.body, '.chapter-navigation a.chapter-link', r.url);
        var latestChap = chEls.length ? chEls[chEls.length - 1].text.trim() : '全一话';
        var status = /完结/.test(r.body) ? '完结' : '连载';
        var info = summary(pid, title, cover, latestChap);
        info.status = status;
        info.latestChapter = latestChap;
        info.tags = tags;
        info.description = meta(r.body, 'description') || meta(r.body, 'og:description') || '';
        return info;
    },

    chapters: function (id) {
        var pid = numericId(id);
        var r = get('/post/' + pid + '.html', env.baseUrl + '/item/%e8%bf%9e%e8%bd%bd');
        var chEls = q(r.body, '.chapter-navigation a.chapter-link', r.url);
        if (!chEls.length) {
            return slots([
                chapter('1', '全一话', '/post/' + pid + '.html')
            ]);
        }
        var isPagedSingleWork = chEls.length > 1 && chEls.every(function (el) {
            return /^第?\s*\d+\s*页$/.test(el.text.trim());
        });
        if (isPagedSingleWork) {
            return slots([
                chapter('1', '全一话 (' + chEls.length + '页)', '/post/' + pid + '.html')
            ]);
        }
        var rows = [];
        for (var i = 0; i < chEls.length; i++) {
            var el = chEls[i];
            var href = el.href || '';
            var ctitle = el.text.trim();
            if (!href || !ctitle) continue;
            var cid = match(href, /\/post\/\d+\/page-(\d+)\.html/) || String(i + 1);
            rows.push(chapter(cid, ctitle, href));
        }
        var list = unique(rows, function (c) { return c.id; });
        var asc = 0, desc = 0, prev = -1;
        for (var j = 0; j < list.length; j++) {
            var n = numeric(list[j].title);
            if (n >= 0) {
                if (prev >= 0) { if (n > prev) asc++; else if (n < prev) desc++; }
                prev = n;
            }
        }
        if (desc > asc) list.reverse();
        return slots(list);
    },

    chapter: function (url) {
        var fullUrl = abs(url, env.baseUrl + '/');
        var pid = match(fullUrl, /\/post\/(\d+)(?:\/page-\d+)?\.html/);
        if (!pid) fail('章节地址无效');
        var r = get(fullUrl, env.baseUrl + '/post/' + pid + '.html');
        var title = text(r.body, 'h1.article-title, .article-header h1, h1').replace(/-三四娱乐\s*$/, '').trim();
        var imgs = san421ExtractPageImages(r.body, r.url);

        // If entering root post URL and it has paged single-work links (第1页..第N页) or .post-page-numbers, merge all pages!
        var chEls = q(r.body, '.chapter-navigation a.chapter-link', r.url);
        var pageLinks = [];
        var isRootPost = new RegExp('/post/' + pid + '\\.html$').test(fullUrl);
        if (isRootPost && chEls.length) {
            var isPagedSingleWork = chEls.every(function (el) {
                return /^第?\s*\d+\s*页$/.test(el.text.trim());
            });
            if (isPagedSingleWork || !imgs.length) {
                var cap = Math.min(chEls.length, 48);
                for (var i = 0; i < cap; i++) {
                    if (chEls[i].href && chEls[i].href !== fullUrl) pageLinks.push(chEls[i].href);
                }
            }
        }
        if (!pageLinks.length) {
            var wpPages = q(r.body, '.post-page-numbers[href], .page-links a[href]', r.url);
            for (var j = 0; j < wpPages.length && pageLinks.length < 48; j++) {
                var hu = wpPages[j].href;
                if (hu && hu !== fullUrl && own(hu)) pageLinks.push(hu);
            }
        }
        pageLinks = unique(pageLinks);
        for (var k = 0; k < pageLinks.length; k++) {
            var pr = get(pageLinks[k], fullUrl);
            var subImgs = san421ExtractPageImages(pr.body, pr.url);
            for (var m = 0; m < subImgs.length; m++) imgs.push(subImgs[m]);
        }
        return pageImages(r.url, imgs, title);
    }
};

