function cinApiTitle(titleObj, fallbackId) {
    if (!titleObj || typeof titleObj !== 'object') return '作品 ' + fallbackId;
    var raw = firstValue(titleObj, ['pretty', 'japanese', 'english']);
    return plain(raw) || ('作品 ' + fallbackId);
