function cinReq(url, headers) {
    try {
        return request(url, 'GET', null, headers);
    } catch (e) {
        return request(url, 'GET', null, headers);
    }
}

function cinListFromQuery(queryText, sortMode, page) {
    var p = Math.max(1, Math.floor(Number(page) || 1));
    var sort = sortMode || 'popular';
    var url = 'https://same.yui.pw/api/v6/search/' + enc(queryText) + '/' + p + '/' + enc(sort);
    var res = json(cinReq(url, {
        Accept: 'application/json',
        Referer: 'https://cin.onl/',
        Origin: 'https://cin.onl'
    }));
    var list = Array.isArray(res && res.result) ? res.result : [];
    var items = [];
    for (var i = 0; i < list.length; i++) {
        var row = list[i];
        var id = row && row.id != null ? String(row.id) : '';
        if (!/^\d+$/.test(id)) continue;
        var title = cinApiTitle(row.title, id);
        var coverUrl = row.cover && row.cover.t ? row.cover.t : '';
        var sub = row.num_pages ? (row.num_pages + 'P') : '';
        var item = summary(id, title, '', sub);
        if (coverUrl) item.cover = cinImageDescriptor(coverUrl);
        items.push(item);
    }
    var numPages = Number(res && res.num_pages) || 0;
    return {
        items: items,
        hasMore: p < numPages && items.length > 0
    };
}

