    if (!title) fail('未取得作品标题');
    var pageImgs = extractChapterPageImages(h, r.url);
    var cover = pageImgs.length ? pageImgs[0] : cleanImgUrl(meta(h, 'og:image'));
    var tags = unique(q(h, '.single-cat a, .single-tag a').map(function (e) {
      return e.text.trim();
    }).filter(Boolean));
    return {
      id: String(rawId),
      title: plain(title),
      cover: cover,
      subtitle: tags.length ? tags[0] : '',
      author: '',
      status: '已完结',
      description: plain(title),
      latestChapter: '全一话',
      tags: tags.slice(0, 12)
