    var firstUrl = abs(url);
    var r1 = fetchPica(firstUrl, null, 4);
    var h1 = r1.body;
    var title = text(h1, 'h1.entry-title') || text(h1, 'h1');
    var allImgs = extractChapterPageImages(h1, r1.url);

    var linkEls = q(h1, '.page-links a[href]', r1.url);
    var seenPages = Object.create(null);
    seenPages[r1.url.replace(/\/+$/, '')] = true;
    var extraPages = [];
    for (var i = 0; i < linkEls.length; i++) {
      var lu = linkEls[i].href;
      if (!lu || !own(lu)) continue;
      var norm = lu.replace(/\/+$/, '');
      if (!seenPages[norm]) {
        seenPages[norm] = true;
        extraPages.push(lu);
      }
    }

    var cap = Math.min(extraPages.length, 90);
    for (var j = 0; j < cap; j++) {
      var pr = fetchPica(extraPages[j], r1.url, 5);
      var pImgs = extractChapterPageImages(pr.body, pr.url);
      for (var k = 0; k < pImgs.length; k++) allImgs.push(pImgs[k]);
    }

    var descriptors = unique(allImgs).map(function (imgUrl) {
      return { url: imgUrl, referer: firstUrl };
    });
    return pageImages(firstUrl, descriptors, plain(title));
  }
};

