function cleanCover(u) {
  u = String(u || '').trim();
  if (!u || /^data:/.test(u) || /nocover\.jpg|jipin-default\.jpg|Loading200x200\.png/i.test(u)) return '';
  return abs(u).replace(/^http:\/\//i, 'https://');
}

function parseBookCards(r) {
  var cards = q(r.body, 'ul.pt-card-7 > li, ul.pt-card-7 li', r.url);
  var items = [];
  for (var i = 0; i < cards.length; i++) {
    var li = cards[i];
    var h = li.html || '';
    var a = one(h, '.pt-name a') || one(h, 'a[href*="/list/"]');
    if (!a || !a.href) continue;
    var id = match(a.href, /\/list\/(\d+)\.html/);
    if (!id) continue;
    var title = plain(a.attrs.title || a.text || attr(h, 'img', 'alt'));
    if (!title) continue;
    var covEl = one(h, 'img');
    var cover = covEl ? cleanCover(image(covEl) || covEl.attrs.src) : '';
    var author = text(h, '.s712').replace(/^作者[：:]\s*/, '').trim();
    var status = text(h, '.s713');
    var sub = [author, status].filter(Boolean).join(' · ');
    items.push(summary(id, title, cover, sub));
  }
  items = unique(items, function (it) { return it.id; });
  var hasMore = one(r.body, 'a.nextPage') != null || !!next(r, '.pagelistbox a');
  return { items: items, hasMore: hasMore && items.length > 0 };
}

function parseChapterAnchors(html, baseUrl, allowNewList) {
  var links = q(html, '#chapterlist li a[href*="/view/"]', baseUrl);
  if (!links.length && allowNewList) links = q(html, '#newchaperlist li a[href*="/view/"]', baseUrl);
  var rows = [];
  for (var i = 0; i < links.length; i++) {
    var a = links[i];
    var cid = match(a.href, /\/view\/([^/.?#]+)\.html/);
    if (!cid || /_start$/i.test(cid)) continue;
    var title = plain(a.text || a.attrs.title || ('第' + (i + 1) + '话'));
    rows.push(chapter(cid, title, a.href));
  }
  return rows;
}

