  if (!u || /^data:/.test(u) || /load\.png$|vip02\.svg$|popBanner|finished\.gif|\/static\//i.test(u)) return '';
  if (/^https?:\/\//i.test(u)) return u.replace(/^http:\/\//i, 'https://');
  if (u.charAt(0) === '/') return IMG_ORIGIN + u;
  return abs(u, IMG_ORIGIN + '/');
}

function isFreeComic(x) {
  if (!x || !x.id) return false;
  if (x.type != null && String(x.type) !== '' && Number(x.type) !== 1) return false;
  if (Number(x.vipcanread || 0) !== 0) return false;
  return true;
}

function parseKeywords(raw) {
  if (!raw) return [];
  return unique(String(raw).split(/[,，\s\/|]+/).map(function (s) { return s.trim(); }).filter(function (s) {
    return !!s && s !== '0' && s.length <= 40;
  }));
}

function mapBook(x) {
  if (Number(x.latest_two_chapters_vip || 0) === 1) {
    xx.cacheSet('lt2:' + x.id, '1');
  }
  var cover = normalizeCover(x.image || x.cover);
  var author = plain(x.auther || x.author || '');
  var lastCh = plain(x.last_chapter_title || '');
  var subParts = [];
  if (author) subParts.push(author);
  if (lastCh) subParts.push(lastCh);
  var row = summary(String(x.id), plain(x.title || ''), cover, subParts.join(' · '));
  if (lastCh) row.latestChapter = lastCh;
  var tags = parseKeywords(x.keyword);
  if (tags.length) row.tags = tags.slice(0, 12);
  return row;
}

function parseApiList(resp) {
  var data = json(resp);
  var res = data && data.result;
  if (!res || !Array.isArray(res.list)) fail('接口缺少漫画列表数据');
  var items = [];
  for (var i = 0; i < res.list.length; i++) {
    if (isFreeComic(res.list[i])) {
      items.push(mapBook(res.list[i]));
    }
  }
  return {
    items: items,
    hasMore: res.lastPage === false && res.list.length > 0
  };
}

function parseEmbeddedChapters(html) {
  var m = html.match(/function\s+getChapterList[\s\S]*?JSON\.parse\("((?:\\.|[^"\\])*)"\)/);
  if (m && m[1]) {
    try {
      var decoded = JSON.parse('"' + m[1] + '"');
      var parsed = JSON.parse(decoded);
      if (parsed && Array.isArray(parsed.list)) return parsed.list;
    } catch (e) {}
  }
  return null;
}

function extractFreeChapters(list, html) {
  var h = String(html || '');
  var mBlock = h.match(/<script[^>]+id="comic_chpater_list"[^>]*>([\s\S]*?)<\/script>/);
  var tpl = mBlock ? mBlock[1] : h;
  var outerVip = /\{\{\s*if\s*\(\s*true\s*\)\s*\}\}/i.test(tpl);
  var allVip = outerVip && /\{\{\s*if\s*\(\s*true\s*\)\s*\}\}\s*<!--\s*純VIP/i.test(tpl);
  if (allVip) return [];
  var lastTwoVip = !outerVip && /\{\{\s*if\s*\(\s*1\s*&&\s*i\s*>=\s*list\.length\s*-\s*2\s*\)\s*\}\}/.test(tpl);

  var rows = [];
  for (var i = 0; i < list.length; i++) {
    if (outerVip && i >= 10 && list.length > 10) break;
    if (lastTwoVip && i >= list.length - 2) break;
    var ch = list[i];
    if (!ch || !ch.id) continue;
    if (Number(ch.isvip || 0) !== 0) continue;
    var title = plain(ch.title || ('第' + (i + 1) + '话'));
    var sec = /^(?:au\s*第?|番外)/i.test(title) ? 1 : 0;
    rows.push(chapter(String(ch.id), title, env.baseUrl + '/home/book/capter/id/' + ch.id, sec));
  }
  var list = unique(rows, function (c) { return c.id; });
  var main = [], extra = [], j;
  for (j = 0; j < list.length; j++) {
    if (list[j].section === 1) extra.push(list[j]);
    else main.push(list[j]);
  }
  function blOrder(arr) {
    var asc = 0, desc = 0, prev = -1;
    for (var k = 0; k < arr.length; k++) {
      var n = numeric(arr[k].title);
      if (n >= 0) { if (prev >= 0) { if (n > prev) asc++; else if (n < prev) desc++; } prev = n; }
    }
    if (desc > asc) arr.reverse();
    return arr;
  }
  return slots(blOrder(main).concat(blOrder(extra)));
}

