  },

  chapters: function (rawId) {
    var id = numericId(rawId);
    var r = get(env.baseUrl + '/home/book/index/id/' + id);
    var list = parseEmbeddedChapters(r.body);
    if (!list || !list.length) {
      try {
        var apiResp = json(get(env.baseUrl + '/home/api/chapter_list/tp/' + id, env.baseUrl + '/home/book/index/id/' + id));
        if (apiResp && apiResp.result && Array.isArray(apiResp.result.list)) {
