        while (imgEntries.length > 5 && imgEntries[imgEntries.length - 1].height > 0 && imgEntries[imgEntries.length - 1].height < 160) {
          imgEntries.pop();
        }
      } catch (e) {}
    }

    if (!imgEntries.length) {
      var imgs = q(h, '.reader-cartoon-image img, img.lazy', chUrl);
      for (var j = 0; j < imgs.length; j++) {
        var rawSrc = image(imgs[j]);
        var norm = normalizeImage(rawSrc);
        if (norm) imgEntries.push({ url: norm, fromImageData: /\.webp(?:[?#]|$)/i.test(norm) });
      }
    }

    var descriptors = [];
    for (var k = 0; k < imgEntries.length; k++) {
      var entry = imgEntries[k];
      var desc = {
        url: entry.url,
        referer: chUrl
      };
      if (applyTransform && entry.fromImageData) {
        desc.transform = {
          type: 'reverseBands',
          axis: 'vertical',
          bands: bands,
          maxHeight: 3999
        };
      }
      descriptors.push(desc);
    }

    return pageImages(chUrl, descriptors, plain(title));
  }
};

