/* Hitomi.si (Hitomi漫) comic source rule. */

function fetchHitomi(u) {
  return request(u, 'GET', null, {
    Referer: env.baseUrl + '/'
  }, {
    read: '1'
  });
}

function keepManga(x) {
  if (!x || !x.manga_id || !x.manga_name) return false;
  var lang = String(x.language || '').toLowerCase();
  if (lang && lang !== 'chinese') return false;
  if (/沒有漢化|没有汉化/.test(String(x.manga_name))) return false;
  return true;
}

function cleanTitle(raw) {
  return plain(String(raw || '')).replace(/\s+/g, ' ').trim();
}

function parseListResponse(r) {
  var d = json(r);
  var raw = Array.isArray(d && d.manga_list) ? d.manga_list : [];
  var items = [];
  for (var i = 0; i < raw.length; i++) {
    var x = raw[i];
    if (!keepManga(x)) continue;
    var row = summary(String(x.manga_id), cleanTitle(x.manga_name), abs(x.manga_cover_img || ''), '中文汉化');
    items.push(row);
  }
  var hasNext = !!(d && d.pagi && d.pagi.button && Number(d.pagi.button.next || 0) > 0);
  return {
    items: items,
    hasMore: hasNext && raw.length > 0
  };
}

var source = {
  filters: function () {
    return [
      group('category', '分类', [
        '中文最新', 'language/chinese',
        '同人志', 'category/doujinshi',
        '单行本', 'category/manga',
        '画集CG', 'category/artistcg',
        '游戏CG', 'category/gamecg',
        '图集', 'category/imageset'
      ])
    ];
  },

  latest: function (page) {
    var p = Math.max(1, Number(page) || 1);
    return parseListResponse(fetchHitomi(env.baseUrl + '/spa/language/chinese?page=' + p));
  },

  category: function (filters, page) {
    var p = Math.max(1, Number(page) || 1);
    var cat = val(filters, 'category', 'language/chinese');
    if (cat === 'language/chinese') {
      return parseListResponse(fetchHitomi(env.baseUrl + '/spa/language/chinese?page=' + p));
    }
    var collected = [];
    var hasMore = false;
    var cur = p;
    for (var step = 0; step < 3; step++) {
      var res = parseListResponse(fetchHitomi(env.baseUrl + '/spa/' + cat + '?page=' + cur));
      for (var i = 0; i < res.items.length; i++) collected.push(res.items[i]);
      hasMore = res.hasMore;
      if (collected.length >= 10 || !hasMore) break;
      cur++;
    }
    return {
      items: unique(collected, function (it) { return it.id; }),
      hasMore: hasMore
    };
  },

  search: function (keyword, page) {
    var kw = String(keyword || '').trim();
    if (!kw) return { items: [], hasMore: false };
    var p = Math.max(1, Number(page) || 1);
    return parseListResponse(fetchHitomi(env.baseUrl + '/spa/search?query=' + enc(kw) + '&page=' + p));
  },

  detail: function (rawId) {
    var id = numericId(rawId);
    var d = json(fetchHitomi(env.baseUrl + '/spa/manga/' + id));
    var det = d && d.detail;
    if (!det || !det.manga_name) fail('未取得作品详情');
    var authors = Array.isArray(d.authors) ? d.authors.map(function (a) { return a.author_name; }).filter(Boolean) : [];
    var tags = Array.isArray(d.tags) ? d.tags.map(function (t) { return t.tag_name; }).filter(Boolean) : [];
    var cover = det.manga_cover_img || det.manga_cover_img_normal || det.manga_cover_img_full || '';
    var chs = Array.isArray(d.chapters) ? d.chapters : [];
    var latestTitle = chs.length ? (chs[chs.length - 1].chapter_title || '全一话') : '全一话';
    return {
      id: id,
      title: cleanTitle(det.manga_name),
      cover: abs(cover),
      subtitle: plain(det.category || ''),
      author: plain(authors.join(', ')),
      status: plain(det.manga_status || '已完结'),
      description: plain(det.manga_description || ''),
      latestChapter: plain(latestTitle),
      tags: tags.slice(0, 16)
    };
  },

  chapters: function (rawId) {
    var id = numericId(rawId);
    var d = json(fetchHitomi(env.baseUrl + '/spa/manga/' + id));
    var list = Array.isArray(d && d.chapters) ? d.chapters : [];
    var readUrl = env.baseUrl + '/spa/manga/' + id + '/read';
    if (!list.length) {
      return slots([chapter(id + '_1', '全一话', readUrl)]);
    }
    var rows = [];
    for (var i = 0; i < list.length; i++) {
      var ch = list[i];
      var cid = ch.chapter_id || ch.chapter_number || (i + 1);
      var title = ch.chapter_title ? plain(ch.chapter_title) : (list.length === 1 ? '全一话' : '第' + (i + 1) + '话');
      rows.push(chapter(String(cid), title, readUrl));
    }
    rows = unique(rows, function (c) { return c.id; });
    var asc = 0, desc = 0, prev = -1;
    for (var j = 0; j < rows.length; j++) {
      var n = numeric(rows[j].title);
      if (n >= 0) {
        if (prev >= 0) {
          if (n > prev) asc++;
          else if (n < prev) desc++;
        }
        prev = n;
      }
    }
    if (desc > asc) rows.reverse();
    return slots(rows);
  },

  chapter: function (url) {
    var u = abs(url);
    var d = json(fetchHitomi(u));
    var cd = (d && d.chapter_detail) || d;
    if (!cd || !cd.chapter_content) fail('章节正文为空');
    var server = firstValue(d, ['server']) || firstValue(cd, ['server']) || 'https://nvme2.bunnyssd.com/';
    if (server.charAt(server.length - 1) !== '/') server += '/';
    var imgs = q(cd.chapter_content, 'img', server);
    var urls = [];
    for (var i = 0; i < imgs.length; i++) {
      var raw = image(imgs[i]);
      if (!raw) continue;
      var full = /^https?:\/\//i.test(raw) ? raw : abs(raw.replace(/^\/+/, ''), server);
      if (full) {
        urls.push({
          url: full,
          referer: env.baseUrl + '/'
        });
      }
    }
    return pageImages(u, urls, cleanTitle(cd.chapter_title || cd.manga_name || ''));
  }
};

