var LIFAN_MOBILE_UA = 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36';

var LIFAN_CATS = {
    shaonvmanhua: {listId: '4', label: '少女漫画'},
    xiee: {listId: '57', label: '邪恶漫画'},
    xieemanhua: {listId: '1', label: '邪恶军团'},
    sexi: {listId: '49', label: '色系军团'},
