function lifanGet(u, referer) {
    var hdrs = {
        'User-Agent': LIFAN_MOBILE_UA,
        Referer: referer || (env.baseUrl + '/')
    };
    try {
        return request(u, 'GET', null, hdrs);
    } catch (e) {
        return request(u, 'GET', null, hdrs);
    }
}

function lifanCleanHtml(html) {
    return String(html || '')
        .replace(/""(\s+class=)/g, '"$1')
        .replace(/alt="[^"<>]*?(\s*\/?>)/g, 'alt=""$1');
}

function lifanSplitId(id) {
    var m = String(id || '').match(/^([a-z0-9]+)_(\d+)$/);
    if (!m || !LIFAN_CATS[m[1]]) fail('作品编号无效');
    return {cat: m[1], num: m[2]};
}

function lifanParseList(r, catSlug, page) {
    var body = lifanCleanHtml(r.body);
    var items = q(body, 'ul.pList li', r.url);
    var rows = [];
    for (var i = 0; i < items.length; i++) {
        var li = items[i];
        var link = one(li.html, 'a.text[href]', r.url) || one(li.html, 'a[href$=".html"]', r.url);
        var href = link && link.href || '';
        var m = href.match(/\/([a-z0-9]+)\/(\d+)\.html/i);
        if (!m || !LIFAN_CATS[m[1]]) continue;
        var id = m[1] + '_' + m[2];
        var title = plain((link.attrs && link.attrs.title) || link.text || '');
        if (!title) continue;
        var imgNode = one(li.html, '.picBox img, img', r.url);
        var cover = imgNode ? abs(image(imgNode), r.url) : '';
        var sub = LIFAN_CATS[m[1]] ? LIFAN_CATS[m[1]].label : catSlug;
        rows.push(summary(id, title, cover, sub));
    }
    var hasNext = false;
    var pgLinks = q(body, '.showpage a[href]', r.url);
    for (var j = 0; j < pgLinks.length; j++) {
        if (/下一页/.test(pgLinks[j].text) && /list_\d+_\d+\.html/.test(pgLinks[j].href || '')) {
            hasNext = true;
            break;
        }
    }
    return {
        items: unique(rows, function (it) { return it.id; }),
        hasMore: hasNext
    };
}

function lifanPageImgs(html, pageUrl) {
    var nodes = q(html, 'div.primary img', pageUrl);
    var out = [];
    for (var i = 0; i < nodes.length; i++) {
        var u = abs(image(nodes[i]), pageUrl);
        if (!u || /\/templets\/|\/ad\/|loading|logo/i.test(u)) continue;
        out.push({
            url: u,
            referer: pageUrl,
            headers: {
                'User-Agent': LIFAN_MOBILE_UA
            }
        });
    }
    return out;
}

