function parseCards(r, chineseOnly) {
  var cards = q(r.body, 'a[href^="/articles/"]', r.url);
  var items = [];
  for (var i = 0; i < cards.length; i++) {
    var a = cards[i];
    var id = match(a.href, /\/articles\/(\d+)(?:[?#]|$)/);
    if (!id) continue;
    var ch = a.html || '';
    var img = one(ch, 'img');
    var alt = img ? String(img.attrs.alt || '') : '';
    if (chineseOnly && ch.indexOf('fi-cn') === -1 && alt.indexOf('中文') === -1) continue;
    var title = text(ch, '.line-clamp-2') || attr(ch, '.line-clamp-2', 'title') || alt.replace(/,\s*中文$/, '').trim();
    if (!title) continue;
    var cover = img ? abs(image(img) || img.attrs.src || '', r.url) : '';
    items.push(summary(id, plain(title), cover, '中文汉化'));
  }
  items = unique(items, function (it) { return it.id; });
  var hasMore = !!(one(r.body, 'a[aria-label="next page"], a[href*="page="]') && (one(r.body, 'a[aria-label="next page"]') != null || next(r)));
