}

function extractMetaBlock(html, labelPrefix) {
  var rows = q(html, '#article-tag-information > div > div');
  for (var i = 0; i < rows.length; i++) {
    var h3 = text(rows[i].html, 'h3');
    if (h3.indexOf(labelPrefix) !== -1) {
      var vals = q(rows[i].html, 'a div, a').map(function (e) { return e.text.trim(); }).filter(function (s) {
        return !!s && s !== 'N/A';
