function parseVodList(r) {
  var boxes = q(r.body, '.stui-vodlist__box', r.url);
  var items = [];
  for (var i = 0; i < boxes.length; i++) {
    var bh = boxes[i].html || '';
    var thumb = one(bh, 'a.stui-vodlist__thumb') || one(bh, 'a[href*="/mangaread/"]');
    if (!thumb || !thumb.href) continue;
    var id = match(thumb.href, /\/mangaread\/(\d+)\.html/);
    if (!id) continue;
    var title = plain(thumb.attrs.title || text(bh, 'h4.title a') || text(bh, '.title a'));
    if (!title) continue;
    var cover = thumb.attrs['data-original'] || attr(bh, 'img', 'data-original') || attr(bh, 'img', 'src');
    var sub = text(bh, '.pic-text');
    items.push(summary(id, title, cover ? abs(cover, r.url) : '', sub));
  }
  items = unique(items, function (it) { return it.id; });
  var hasMore = !!next(r, '.stui-page a, ul.stui-page a, a');
