}

var source = {
  filters: function () {
    return [
      group('cate', '分类', ['全部', 'all', '韩漫', '韩漫', '日漫', '日漫', '3D', '3D', '短篇', '短篇', '同性', '同性']),
      group('order', '排序', ['最热', 'hits', '最新', 'time']),
      group('status', '进度', ['全部', 'all', '连载中', 'serialized', '已完结', 'completed'])
    ];
  },

  latest: function (page) {
    var p = Math.max(1, Number(page) || 1);
    return parseVodList(fetchRouman(env.baseUrl + '/mangacata/all/ob/hits/st/all/page/' + p));
  },

  category: function (filters, page) {
    var p = Math.max(1, Number(page) || 1);
    var cate = val(filters, 'cate', 'all') || 'all';
    var order = val(filters, 'order', 'hits') || 'hits';
    var st = val(filters, 'status', 'all') || 'all';
    var u = env.baseUrl + '/mangacata/' + enc(cate) + '/ob/' + enc(order) + '/st/' + enc(st) + '/page/' + p;
    return parseVodList(fetchRouman(u));
  },

  search: function (keyword, page) {
    var kw = String(keyword || '').trim();
    var p = Math.max(1, Number(page) || 1);
    if (!kw || p > 1) return { items: [], hasMore: false };
    var res = parseVodList(fetchRouman(env.baseUrl + '/cata.php?key=' + enc(kw) + '&submit='));
    res.hasMore = false;
    return res;
  },

  detail: function (rawId) {
    var id = numericId(rawId);
    var u = env.baseUrl + '/mangaread/' + id + '.html';
    var r = fetchRouman(u);
    var h = r.body;
    var title = text(h, '.stui-content__detail h1.title').replace(/^[《「【]+|[》」】]+$/g, '').trim() || text(h, 'h1');
    if (!title) fail('未取得作品标题');
    var cover = attr(h, '.stui-content__thumb a', 'data-original') ||
      attr(h, '.stui-content__thumb img', 'data-original') ||
      attr(h, '.stui-content__thumb img', 'src');
    var author = '';
    var status = '';
    var tags = [];
    var datas = q(h, '.stui-content__detail p.data');
    for (var i = 0; i < datas.length; i++) {
      var dt = datas[i].text.trim();
      var dh = datas[i].html || '';
      if (/作者/.test(dt)) {
        author = q(dh, 'a').map(function (e) { return e.text.trim(); }).join(', ') || dt.replace(/^作者[：:]\s*/, '').trim();
      } else if (/类型|分类|标签/.test(dt)) {
        tags = tags.concat(q(dh, 'a').map(function (e) { return e.text.trim(); }).filter(Boolean));
      } else if (/更新|状态/.test(dt)) {
        status = dt.replace(/^(?:最后更新|状态)[：:]\s*/, '').trim();
      }
    }
    var desc = text(h, '.detail-sketch') || text(h, '.stui-content__detail .desc');
    var chEls = q(h, 'ul.stui-content__playlist li a');
    var latestCh = chEls.length ? chEls[chEls.length - 1].text.trim() : '';
    return {
      id: id,
      title: plain(title),
      cover: cover ? abs(cover, r.url) : '',
      subtitle: author || '',
      author: plain(author),
      status: status || '连载中',
      description: plain(desc || ''),
      latestChapter: plain(latestCh),
      tags: unique(tags).slice(0, 12)
    };
  },

  chapters: function (rawId) {
    var id = numericId(rawId);
    var r = fetchRouman(env.baseUrl + '/mangaread/' + id + '.html');
    var links = q(r.body, 'ul.stui-content__playlist li a', r.url);
    var rows = [];
    for (var i = 0; i < links.length; i++) {
      var a = links[i];
      var cid = match(a.href, /\/mangaread\/\d+\/(\d+)\.html/);
      if (!cid) continue;
      rows.push(chapter(cid, plain(a.text || ('第' + (i + 1) + '话')), a.href));
    }
    if (!rows.length) fail('没有取得本书可读章节');
    rows = unique(rows, function (c) { return c.id; });
    if (!rows.length) fail('没有取得本书可读章节');
    var asc = 0, desc = 0, prev = -1;
    for (var j = 0; j < rows.length; j++) {
      var n = numeric(rows[j].title);
      if (n >= 0) {
        if (prev >= 0) { if (n > prev) asc++; else if (n < prev) desc++; }
        prev = n;
      }
    }
    if (desc > asc) rows.reverse();
    return slots(rows);
  },

  chapter: function (url) {
    var u = abs(url);
    var r = fetchRouman(u);
    var h = r.body;
    var title = text(h, 'h1, .stui-pannel__head h3, title');
    var imgs = q(h, 'img.lazyload, img[data-original*="18rouman"], img[src*="18rouman"]', u);
    var urls = [];
    for (var i = 0; i < imgs.length; i++) {
      var raw = image(imgs[i]);
      if (!raw || /yandex|watch|logo|load/i.test(raw)) continue;
      var full = abs(raw, u).replace(/^http:\/\//i, 'https://');
      if (full) urls.push({ url: full, referer: u });
    }
    return pageImages(u, urls, plain(title));
  }
};

