    var id = match(a.href, /\/album\/(\d+)\.html/);
    if (!id) continue;
    var title = text(ch, '.m-t-5 a') || text(ch, '.video-title') || attr(ch, 'img', 'title') || attr(ch, 'img', 'alt');
    if (!title) continue;
    var imgEl = one(ch, 'img');
