    var author = q(ch, 'a[href*="author"]').map(function (e) { return e.text.trim(); }).join(', ');
    var sub = [author, status].filter(Boolean).join(' · ');
    var row = summary(id, plain(title), cover, sub);
    var tags = q(ch, '.tags a.tag').map(function (e) { return e.text.trim(); }).filter(Boolean);
