/* TIBIU漫画 (comic.tibiu.net) comic source rule. */

function cleanText(raw) {
  return plain(String(raw || ''))
    .replace(/&quot\s*br\s*\/?&quot/gi, ' ')
    .replace(/&quot;/gi, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

function normImg(u) {
  u = String(u || '').trim();
  if (!u || /empty\.png$/i.test(u)) return '';
  return abs(u).replace(/^http:\/\//i, 'https://');
}

function isFreeComic(x) {
  if (!x || !x.id) return false;
  if (Number(x.pay || 0) !== 0) return false;
  if (Number(x.cion || 0) !== 0) return false;
  if (x.nums != null && String(x.nums) !== '' && Number(x.nums) <= 0) return false;
  return true;
}

function parseTags(raw) {
  if (!raw) return [];
  var arr = Array.isArray(raw) ? raw : String(raw).split(/[\s,，/|]+/);
  return unique(arr.map(function (s) { return String(s || '').trim(); }).filter(function (s) {
    return !!s && s.length <= 24;
  }));
}

function mapBook(x) {
  var cover = normImg(x.pic) || normImg(x.picx);
  var author = cleanText(x.author || '');
  var ser = cleanText(x.serialize || '');
  var sub = [author, ser].filter(Boolean).join(' · ');
  var row = summary(String(x.id), cleanText(x.name || ''), cover, sub);
  if (x.chapter_name) row.latestChapter = cleanText(x.chapter_name);
  var tags = parseTags(x.tags);
  if (tags.length) row.tags = tags.slice(0, 12);
  return row;
}

function mapApiRows(rawList, pageSize) {
  var items = [];
  for (var i = 0; i < rawList.length; i++) {
    if (isFreeComic(rawList[i])) items.push(mapBook(rawList[i]));
  }
  return {
    items: items,
    hasMore: rawList.length >= pageSize
  };
}

