      img = one(cardHtml, ".uk-card-media-top img, img", url);
      cover = itsSafeUrl(image(img), url);
      title = plain(text(cardHtml, "p a[href*='bofang'], .uk-card-title") || (a.attrs && a.attrs.title) || a.text);
      if (!title) continue;
      items.push(summary(cid, title, cover, ""));
