  }

  // 3) Search list (.tabul li)
  if (!items.length) {
    var sLinks = q(html, ".tabul li a.item-link[href*='bofang'], .tabul li a[href*='bofang']", url);
    for (i = 0; i < sLinks.length; i++) {
      a = sLinks[i];
      cid = match(a.href, /[?&]kuid=(\d+)/);
      if (!cid) continue;
      img = one(a.html, ".item-media img, img", url);
      cover = itsSafeUrl(image(img), url);
