  return false;
}

var source = {
  validate: function () { return true; },
  filters: function () {
    var sortG = group("sort", "排序", C18_SORTS);
    sortG.exclusiveGroup = "primary";
    var tagG = group("tag", "標籤", C18_TAGS);
    tagG.exclusiveGroup = "primary";
    return [sortG, tagG];
  },
  latest: function (page) {
    var p = c18Page(page);
    var r = get(p === 1 ? "/" : "/?page=" + p);
    return c18ParseCards(r);
  },
  category: function (filters, page) {
    var p = c18Page(page);
    var f = filters || {};
    var sort = val(f, "sort", "");
    var tag = val(f, "tag", "");
    if (sort && !c18ValidPair(C18_SORTS, sort)) fail("排序参数无效");
    if (tag && !c18ValidPair(C18_TAGS, tag)) fail("标签参数无效");
    if (sort && tag) fail("排序与标签筛选互斥，请仅选其一");
    var base = tag ? "/q/" + enc(tag) : "/";
    var qs = [];
    if (sort) qs.push("sort=" + enc(sort));
    if (p > 1 || (!tag && !sort)) qs.push("page=" + p);
    var url = base + (qs.length ? "?" + qs.join("&") : "");
    return c18ParseCards(get(url));
  },
  search: function (keyword, page) {
    var kw = plain(keyword);
    if (!kw) return { items: [], hasMore: false };
