    var url = "/?q=" + enc(kw) + (p > 1 ? "&page=" + p : "");
    return c18ParseCards(get(url));
  },
  detail: function (id) {
    var vid = c18Id(id);
    var r = get("/v/" + vid);
    var html = r.body;
    var title = plain(meta(html, "og:title") || text(html, "h1.title").replace(/\s*\{\{[\s\S]*$/, ""));
    if (!title) fail("作品标题缺失");
    var coverImg = one(html, ".row.mb-4 a[href*='/story/'] img, .row.mb-4 img", r.url);
    var cover = c18SafeUrl((coverImg && image(coverImg)) || meta(html, "og:image"), r.url);
    var author = "";
    var desc = "";
    var tags = [];
    var rows = q(html, ".row.mb-4 .my-2", r.url);
    for (var i = 0; i < rows.length; i++) {
      var spans = q(rows[i].html, "span", r.url);
      if (spans.length >= 2) {
        var k = plain(spans[0].text);
        var v = plain(spans[spans.length - 1].text);
        if (k.indexOf("作者") >= 0 && v) author = v;
        else if ((k.indexOf("簡介") >= 0 || k.indexOf("简介") >= 0) && v) desc = v;
      }
      if (rows[i].text.indexOf("標籤") >= 0 || rows[i].text.indexOf("标签") >= 0) {
        var tLinks = q(rows[i].html, "a[href*='/q/']", r.url);
        for (var j = 0; j < tLinks.length; j++) {
          var t = plain(tLinks[j].text);
          if (t) tags.push(t);
        }
      }
    }
    if (!desc) {
      var mDesc = plain(meta(html, "description"));
      if (mDesc && mDesc !== title) desc = mDesc;
    }
    var out = summary(vid, title, cover, author);
    out.author = author;
    out.description = desc;
    out.tags = unique(tags).slice(0, 64);
    return out;
  },
  chapters: function (id) {
    var vid = c18Id(id);
    var r = get("/v/" + vid);
    var links = q(r.body, "a.btn[href*='/story/']", r.url);
    if (!links.length) links = q(r.body, ".container a[href*='/story/'], a[href*='/story/']", r.url);
    var rows = [];
    for (var i = 0; i < links.length; i++) {
      var a = links[i];
      var t = plain(a.text);
      if (!t || !a.href) continue;
      var sid = match(path(a.href), /^\/story\/(\d+)(?:\/full)?$/);
      if (!sid) continue;
      rows.push(chapter(sid, t, "/story/" + sid + "/full", 0));
    }
    var list = unique(rows, function (c) { return c.id; });
    var asc = 0, desc = 0, prev = -1;
