      var n = numeric(list[j].title);
      if (n >= 0) {
        if (prev >= 0) { if (n > prev) asc++; else if (n < prev) desc++; }
        prev = n;
      }
    }
    if (desc > asc) list.reverse();
    return slots(list);
  },
  chapter: function (url) {
