    var sid = match(path(u), /^\/story\/(\d+)(?:\/full)?$/);
    if (!sid) fail("章节地址无效");
    var fullPath = "/story/" + sid + "/full";
    var r = get(fullPath);
    var imgs = q(r.body, ".cartoon-image img, img[src*='/images/image/'], img[data-src*='/images/image/']", r.url);
    var out = [];
