    var h = card.html || '';
    var covTitle = plain(text(h, 'h3', r.url) || attr(h, 'img', 'alt', r.url));
    if (!covTitle) continue;
    var im = one(h, 'img', r.url);
    var cov = im ? image(im) : '';
    cov = cov ? abs(cov, r.url) : '';
    var spans = q(h, 'div.text-xs span', r.url);
    var subParts = [];
    for (var j = 0; j < spans.length; j++) {
      var st = plain(spans[j].text);
      if (st && st !== '·' && st !== 'Anonymous') subParts.push(st);
    }
    var relId = path(abs(href, r.url));
    items.push(summary(relId, covTitle, cov, subParts.join(' · ')));
  }
  items = unique(items, function (it) { return it.id; });
  var hasMore = false;
  var pLinks = q(r.body, 'a[href*="page="]', r.url);
  for (var k = 0; k < pLinks.length; k++) {
    var ph = pLinks[k].href || '';
    var pt = plain(pLinks[k].text);
    var m = match(ph, /[?&]page=(\d+)/);
    var target = m ? Number(m) : 0;
    if (target > curPage || /下一页|Next|»/.test(pt)) {
      hasMore = true;
      break;
    }
  }
  return { items: items, hasMore: hasMore };
}

function mkExtractPhotos(r) {
  var imgs = [];
  var nodes = q(r.body, '.photo-item img', r.url);
  for (var i = 0; i < nodes.length; i++) {
    var u = image(nodes[i]);
    if (u) imgs.push(abs(u, r.url));
  }
  if (!imgs.length) {
    var allImgs = q(r.body, 'main img, article img', r.url);
    for (var j = 0; j < allImgs.length; j++) {
      var u2 = image(allImgs[j]);
      if (u2 && u2.indexOf('/photos/') >= 0) imgs.push(abs(u2, r.url));
    }
  }
  return imgs;
}

