    var cov = meta(r.body, 'og:image');
    if (!cov) {
      var im = one(r.body, '.photo-item img', r.url);
      cov = im ? image(im) : '';
    }
    cov = cov ? abs(cov, r.url) : '';
    var tagLinks = q(r.body, 'a[href*="/zh/categories/"], a[href*="/zh/series/"], a[href*="/zh/tags/"]', r.url);
    var tags = [];
