  },
  chapters: function (id) {
    return slots([chapter(id, '完整相册', abs(id, BASE + '/'), 0)]);
  },
  chapter: function (url) {
    var baseUrl = abs(url, BASE + '/').split('#')[0];
    var baseNoPage = baseUrl.replace(/([?&])page=\d+&?/, '$1').replace(/[?&]$/, '');
    var r1 = mkGet(baseNoPage);
    var title = plain(text(r1.body, 'h1', r1.url)) || '完整相册';
    var photos = mkExtractPhotos(r1);
    var maxPage = 1;
    var pLinks = q(r1.body, 'a[href*="page="]', r1.url);
    for (var i = 0; i < pLinks.length; i++) {
      var m = match(pLinks[i].href, /[?&]page=(\d+)/);
      if (m) {
        var n = Number(m);
        if (n > maxPage) maxPage = n;
      }
    }
    var cap = maxPage > 80 ? 80 : maxPage;
    var sep = baseNoPage.indexOf('?') >= 0 ? '&' : '?';
