function mtlGet(url, ref) {
  try {
    return get(url, ref);
  } catch (e) {
    if (/timed out|reset|closed|EOF/i.test(String(e))) return get(url, ref);
    throw e;
  }
}

function mtlPageNum(p) {
  var n = Number(p || 1);
  return !isFinite(n) || n < 1 ? 1 : Math.floor(n);
}

function mtlParseList(r, curPage) {
  var items = [];
  var cards = q(r.body, 'div.col-lg-3', r.url);
  for (var i = 0; i < cards.length; i++) {
    var h = cards[i].html || '';
    var a = one(h, 'a[href*="/item/"]', r.url);
    if (!a || !a.href) continue;
    var href = abs(a.href, r.url);
    if (!href || href.indexOf('/item/') < 0) continue;
    var title = plain(text(h, '.my-card-title', r.url)) || plain(attr(h, 'img', 'alt', r.url));
    if (!title) continue;
    var im = one(h, 'img', r.url);
    var cov = im ? image(im) : '';
    cov = cov ? abs(cov, r.url) : '';
    var infoDivs = q(h, '.card-body div.mb-1', r.url);
    var sub = infoDivs.length ? plain(infoDivs[0].text) : '';
    items.push(summary(path(href), title, cov, sub));
  }
  items = unique(items, function (it) { return it.id; });

  var hasMore = false;
  var pLinks = q(r.body, '.pagination a[href]', r.url);
  for (var j = 0; j < pLinks.length; j++) {
    var ph = pLinks[j].href || '';
    var pt = plain(pLinks[j].text);
    var m = match(ph, /index_(\d+)\.html/);
    var target = m ? Number(m) : 0;
    if (target > curPage || /下一页|下页|›|»/.test(pt)) {
      hasMore = true;
      break;
    }
  }
  return { items: items, hasMore: hasMore };
}

function mtlExtractPhotos(r) {
  var imgs = [];
  var nodes = q(r.body, '.mb-4.container-inner-fix-m img', r.url);
  if (!nodes.length) nodes = q(r.body, 'img[src*="/p/"]', r.url);
  for (var i = 0; i < nodes.length; i++) {
    var u = image(nodes[i]);
    if (u && u.indexOf('/poster/') < 0) imgs.push(abs(u, r.url));
  }
  return imgs;
}

var source = {
  filters: function () {
    return [group('category', '分类', MTL_CAT_PAIRS)];
  },
  latest: function (page) {
    var p = mtlPageNum(page);
    if (p <= 1) {
      var res1 = mtlParseList(mtlGet(BASE + '/'), 1);
      if (res1.items.length > 0) res1.hasMore = true;
      return res1;
    }
    var pools = ['guochan', 'rihan', 'gangtai'];
    var idx = p - 2;
    var slug = pools[idx % pools.length];
    var subPage = Math.floor(idx / pools.length) + 1;
    if (subPage > 50) return { items: [], hasMore: false };
    var url = subPage <= 1 ? BASE + '/' + slug + '/' : BASE + '/' + slug + '/index_' + subPage + '.html';
    var resN = mtlParseList(mtlGet(url, BASE + '/'), subPage);
    if (resN.items.length > 0 && subPage < 39) resN.hasMore = true;
    return resN;
  },
  category: function (selected, page) {
    var p = mtlPageNum(page);
    var slug = val(selected, 'category', 'all');
    if (!slug || slug === 'all') return source.latest(p);
    var url = p <= 1 ? BASE + '/' + slug + '/' : BASE + '/' + slug + '/index_' + p + '.html';
    return mtlParseList(mtlGet(url, BASE + '/'), p);
  },
  search: function (keyword, page) {
    var kw = plain(keyword || '');
    if (!kw) return { items: [], hasMore: false };
    var p = mtlPageNum(page);
    if (p > 1) return { items: [], hasMore: false };
    return mtlParseList(mtlGet(BASE + '/search?q=' + enc(kw), BASE + '/'), 1);
  },
  detail: function (id) {
    var url = abs(id, BASE + '/');
    var r = mtlGet(url);
    var title = plain(text(r.body, 'h1, .h4, .my-card-title', r.url) || meta(r.body, 'og:title'));
    var itemNum = match(path(url), /\/item\/(\d+)\.html/);
    var cov = meta(r.body, 'og:image');
    if (!cov && itemNum) cov = BASE + '/poster/' + itemNum + '.jpg';
    if (!cov) {
      var imgs = mtlExtractPhotos(r);
      if (imgs.length) cov = imgs[0];
    }
    cov = cov ? abs(cov, r.url) : '';
    var tagLinks = q(r.body, 'a[href^="/t/"]', r.url);
    var tags = [];
    for (var i = 0; i < tagLinks.length; i++) {
      var t = plain(tagLinks[i].text);
      if (t && tags.indexOf(t) < 0 && tags.length < 12) tags.push(t);
    }
    return {
      id: String(id),
      title: title || String(id),
      cover: cov,
      status: '已完结',
      tags: tags,
      description: plain(meta(r.body, 'description'))
    };
  },
  chapters: function (id) {
    return slots([chapter(id, '完整相册', abs(id, BASE + '/'), 0)]);
  },
  chapter: function (url) {
    var itemUrl = abs(url, BASE + '/').split('#')[0];
    var r1 = mtlGet(itemUrl);
    var title = plain(text(r1.body, 'h1, .h4', r1.url)) || '完整相册';
    var photos = mtlExtractPhotos(r1);

    var maxPage = 1;
    var pLinks = q(r1.body, '.pagination a[href]', r1.url);
    for (var i = 0; i < pLinks.length; i++) {
      var ph = pLinks[i].href || '';
      var m = match(ph, /_(\d+)\.html/);
      if (m) {
        var n = Number(m);
        if (n > maxPage) maxPage = n;
      }
    }
    var cap = maxPage > 80 ? 80 : maxPage;
    var stem = itemUrl.replace(/\.html$/i, '');
    for (var p = 2; p <= cap; p++) {
      var nextUrl = stem + '_' + p + '.html';
      var rn = mtlGet(nextUrl, itemUrl);
      var pImgs = mtlExtractPhotos(rn);
      for (var j = 0; j < pImgs.length; j++) photos.push(pImgs[j]);
    }
    return pageImages(itemUrl, photos, title);
  }
};

