function mmGet(url, ref) {
  try {
    return get(url, ref);
  } catch (e) {
    if (/timed out|reset|closed|EOF/i.test(String(e))) return get(url, ref);
    throw e;
  }
}

function mmPageNum(p) {
  var n = Number(p || 1);
  return !isFinite(n) || n < 1 ? 1 : Math.floor(n);
}

function mmParseList(r, curPage) {
  var items = [];
  var cards = q(r.body, 'div.card', r.url);
  for (var i = 0; i < cards.length; i++) {
    var h = cards[i].html || '';
    var a = one(h, 'a.card-permalink[href], a[href*="thread-"]', r.url);
    if (!a || !a.href) continue;
    var href = abs(a.href, r.url);
    if (!href || href.indexOf('thread-') < 0) continue;

    var fig = one(h, '.card-figure[ui8-image]', r.url);
    var cov = (fig && fig.attrs && fig.attrs['ui8-image']) || '';
    if (!cov) {
      var im = one(h, 'img', r.url);
      cov = im ? ((im.attrs && (im.attrs['ui8-image'] || im.attrs.zoomfile)) || image(im)) : '';
    }
    cov = cov ? abs(cov, r.url) : '';

    var pEl = one(h, 'p', r.url);
    var title = '';
    if (pEl && pEl.html) {
      var parts = pEl.html.split(/<br\s*\/?>/i);
      if (parts.length > 1) title = plain(parts[parts.length - 1]);
      if (!title) title = plain(pEl.text).replace(/^\d+(?:\s+\d+)*\s+/, '').trim();
    }
    if (!title) title = plain(a.text);
    if (!title) continue;

    items.push(summary(path(href), title, cov, ''));
  }
  items = unique(items, function (it) { return it.id; });

  var hasMore = false;
  var pLinks = q(r.body, '.pg a[href]', r.url);
  for (var j = 0; j < pLinks.length; j++) {
    var ph = pLinks[j].href || '';
    var pt = plain(pLinks[j].text);
    var m1 = match(ph, /forum-\d+-(\d+)\.html/);
    var m2 = match(ph, /[?&]page=(\d+)/);
    var target = Number(m1 || m2 || 0);
    if (target > curPage || /下一页|下页|›|»/.test(pt) || (pLinks[j].attrs && pLinks[j].attrs.class && pLinks[j].attrs.class.indexOf('nxt') >= 0)) {
      hasMore = true;
      break;
    }
  }
  return { items: items, hasMore: hasMore };
}

function mmExtractImages(r) {
  var imgs = [];
  var nodes = q(r.body, 'img[zoomfile], img[ui8-image], .t_f img', r.url);
  for (var i = 0; i < nodes.length; i++) {
    var a = nodes[i].attrs || {};
    var u = a.zoomfile || a['ui8-image'] || a.file || image(nodes[i]);
    if (!u || /none\.gif|smiley|avatar|common\//i.test(u)) continue;
    var full = abs(u, r.url);
    if (full && full.indexOf('attachment.') >= 0) imgs.push(full);
    else if (full && /\.(jpg|jpeg|png|webp|gif)(\?|$)/i.test(full) && full.indexOf('/static/') < 0) imgs.push(full);
  }
  return imgs;
}

