  },
  category: function (selected, page) {
    var p = mmPageNum(page);
    var b = val(selected, 'board', 'all');
    var ord = val(selected, 'order', 'all');
    if (ord === 'all' || !ord) {
      if (!b || b === 'all') return source.latest(p);
      return mmParseList(mmGet(BASE + '/' + b + '-' + p + '.html'), p);
    }
    var fid = (!b || b === 'all') ? '2' : match(b, /^forum-(\d+)$/);
    if (!fid) fail('板块参数无效');
    var qs = 'mod=forumdisplay&fid=' + enc(fid);
    if (ord === 'heat') qs += '&filter=heat&orderby=heats';
    else if (ord === 'views') qs += '&filter=reply&orderby=views';
    else if (ord === 'month') qs += '&filter=reply&orderby=views&dateline=2592000';
    else if (ord === 'year') qs += '&filter=reply&orderby=views&dateline=31536000';
    else fail('排序参数无效');
    if (p > 1) qs += '&page=' + p;
    return mmParseList(mmGet(BASE + '/forum.php?' + qs), p);
  },
  search: function (keyword, page) {
    var kw = plain(keyword || '');
    if (!kw) return { items: [], hasMore: false };
    var p = mmPageNum(page);
    var cacheKey = 'mmrgb_srch_' + kw;
    var srchBase = p > 1 ? xx.cacheGet(cacheKey) : '';
    var r;
    if (p > 1 && srchBase) {
      var nextUrl = srchBase.replace(/([?&])page=\d+&?/, '$1').replace(/[?&]$/, '') + '&page=' + p;
      r = mmGet(nextUrl);
    } else {
      r = mmGet(BASE + '/search.php?mod=forum&srchtxt=' + enc(kw) + '&searchsubmit=yes');
      var msg = plain(text(r.body, '#messagetext', r.url));
      if (msg && !q(r.body, 'div.card', r.url).length) fail(msg);
      if (r.url && r.url.indexOf('searchid=') >= 0) xx.cacheSet(cacheKey, r.url);
      if (p > 1 && r.url) {
        var pageUrl = r.url.replace(/([?&])page=\d+&?/, '$1').replace(/[?&]$/, '') + '&page=' + p;
        r = mmGet(pageUrl);
      }
    }
    return mmParseList(r, p);
  },
  detail: function (id) {
    var url = abs(id, BASE + '/');
    var r = mmGet(url);
    var title = plain(text(r.body, '#thread_subject', r.url));
    if (!title) title = plain(text(r.body, 'title', r.url)).replace(/\s*-\s*[^-]+-\s*MMRGB\s*$/i, '').trim();
    var imgs = mmExtractImages(r);
    var cov = imgs.length ? imgs[0] : abs(meta(r.body, 'og:image'), r.url);
    var tagLinks = q(r.body, '.ptg a, .bm_h a[href*="forum-"]', r.url);
    var tags = [];
    for (var i = 0; i < tagLinks.length; i++) {
      var t = plain(tagLinks[i].text);
      if (t && tags.indexOf(t) < 0 && tags.length < 12) tags.push(t);
    }
    return {
      id: String(id),
      title: title || String(id),
      cover: cov || '',
      status: '已完结',
      tags: tags,
      description: ''
    };
  },
  chapters: function (id) {
    return slots([chapter(id, '完整相册', abs(id, BASE + '/'), 0)]);
  },
  chapter: function (url) {
    var threadUrl = abs(url, BASE + '/').split('#')[0];
    var r1 = mmGet(threadUrl);
    var title = plain(text(r1.body, '#thread_subject', r1.url)) || '完整相册';
    var photos = mmExtractImages(r1);
    var tidMatch = match(threadUrl, /thread-(\d+)-/);
    var maxPage = 1;
    var pLinks = q(r1.body, '.pg a[href*="thread-"]', r1.url);
    for (var i = 0; i < pLinks.length; i++) {
      var m = match(pLinks[i].href, /thread-\d+-(\d+)-/);
      if (m) {
        var n = Number(m);
        if (n > maxPage) maxPage = n;
      }
    }
    var cap = maxPage > 60 ? 60 : maxPage;
    if (tidMatch && cap > 1) {
      for (var p = 2; p <= cap; p++) {
        var nextUrl = BASE + '/thread-' + tidMatch + '-' + p + '-1.html';
        var rn = mmGet(nextUrl, threadUrl);
        var pImgs = mmExtractImages(rn);
        for (var j = 0; j < pImgs.length; j++) photos.push(pImgs[j]);
      }
    }
    return pageImages(threadUrl, photos, title);
  }
};

