function jbGet(url, ref) {
  try {
    return get(url, ref);
  } catch (e) {
    if (/timed out|reset|closed|EOF/i.test(String(e))) return get(url, ref);
    throw e;
  }
}

function jbPageNum(p) {
  var n = Number(p || 1);
  return !isFinite(n) || n < 1 ? 1 : Math.floor(n);
}

function jbCleanImgUrl(u) {
  if (!u) return '';
  return String(u).trim().replace(/\/+$/, '').replace(/^http:\/\//i, 'https://');
}

function jbCleanTitle(t) {
  return plain(t).replace(/\s*[—–-]\s*Jablehk.*$/i, '').trim();
}

function jbParseCollection(col, page) {
  var p = jbPageNum(page);
  var url = BASE + '/' + col + '?format=json';
  if (p > 1) {
    var off = xx.cacheGet('jb_off_' + col + '_' + p);
    if (!off) return { items: [], hasMore: false };
    url = BASE + '/' + col + '?offset=' + enc(off) + '&format=json';
  }
  var data = json(jbGet(url));
  var rows = data.items || [];
  var items = [];
  for (var i = 0; i < rows.length; i++) {
    var it = rows[i];
    if (!it || !it.fullUrl) continue;
    var title = jbCleanTitle(it.title || it.fullUrl);
    if (!title) continue;
    var cov = jbCleanImgUrl(it.assetUrl || '');
    var tags = (it.tags || []).slice(0, 3).join(' · ');
    items.push(summary(it.fullUrl, title, cov, tags));
  }
  var pag = data.pagination;
  var hasMore = !!(pag && pag.nextPage && pag.nextPageOffset);
  if (hasMore) {
    xx.cacheSet('jb_off_' + col + '_' + (p + 1), String(pag.nextPageOffset));
  }
  return { items: unique(items, function (x) { return x.id; }), hasMore: hasMore };
}

function jbExtractAlbumImages(r) {
  var imgs = [];
  var nodes = q(r.body, '.sqs-gallery-block img, .gallery-grid img, main img, article img', r.url);
  for (var i = 0; i < nodes.length; i++) {
    var a = nodes[i].attrs || {};
    var raw = a['data-src'] || a['data-image'] || a.src || '';
    var u = jbCleanImgUrl(raw);
    if (!u || /^data:/.test(u)) continue;
    var full = abs(u, r.url);
    if (full && full.indexOf('images.squarespace-cdn.com') >= 0) {
      imgs.push(full);
    }
  }
  return unique(imgs, function (u) { return u; });
}

