  var cards = q(r.body, '.wp-block-post', r.url);
  var items = [];
  var seen = Object.create(null);
  for (var i = 0; i < cards.length; i++) {
    var html = cards[i].html;
    var link = one(html, 'a[href*="/content/"]', r.url);
    if (!link) continue;
    var pth = path(link.href).replace(/^\/content\//, '').replace(/\/+$/, '');
