  var rid = hd4kId(id);
  var r = get('/content/' + hd4kSafeUri(rid));
  if (!own(r.url)) fail('图集发生跳转');
  var title = plain(text(r.body, '.wp-block-post-title, h1.entry-title, h2.entry-title', r.url) || meta(r.body, 'og:title').replace(/\s*-\s*4KHD\s*$/i, ''));
  var imgs = hd4kPageImgs(r.body, r.url);
