var source = {
  filters: function () {
    return [group('category', '分类', HD4K_CATS)];
  },
  latest: function (page) {
    var p = hd4kPage(page);
    return hd4kList(p === 1 ? '/' : '/?query-3-page=' + p, p);
  },
  category: function (filters, page) {
    var p = hd4kPage(page);
    var cat = val(filters || {}, 'category', 'all');
    if (cat === 'all') return source.latest(p);
    if (!hd4kValidCat(cat)) fail('分类无效');
    return hd4kList(p === 1 ? cat : cat + '?query-3-page=' + p, p);
  },
  search: function (keyword, page) {
    var p = hd4kPage(page);
    var kw = String(keyword || '').trim();
    if (!kw) return { items: [], hasMore: false };
    var route = '/search/' + enc(kw) + (p > 1 ? '/page/' + p : '');
    return hd4kList(route, p);
  },
  detail: function (id) {
    var book = hd4kBook(id);
    return { id: book.id, title: book.title, cover: book.cover };
  },
  chapters: function (id) {
    var book = hd4kBook(id);
    return slots([chapter(book.id, '完整相册', book.url, 0)]);
  },
  chapter: function (url) {
    var target = abs(url, env.baseUrl);
    if (!target || !own(target)) fail('章节地址无效');
    var first = get(target);
    if (!own(first.url)) fail('章节发生跳转');
    var imgs = hd4kPageImgs(first.body, first.url);
    var maxP = hd4kMaxPage(first.body, first.url);
    if (maxP > 125) maxP = 125;
    var baseNoPage = first.url.replace(/\/\d+\/?$/, '').replace(/\/+$/, '');
    for (var p = 2; p <= maxP; p++) {
      var res = get(baseNoPage + '/' + p, first.url);
      if (!own(res.url)) break;
      var more = hd4kPageImgs(res.body, res.url);
      if (!more.length) break;
      for (var j = 0; j < more.length; j++) imgs.push(more[j]);
    }
    imgs = unique(imgs);
    if (!imgs.length) fail('没有取得相册图片');
    var title = plain(text(first.body, '.wp-block-post-title, h1.entry-title, h2.entry-title', first.url) || meta(first.body, 'og:title').replace(/\s*-\s*4KHD\s*$/i, ''));
    return pageImages(first.url, imgs, title);
  }
};

