function anId(raw) {
  var s = String(raw || '').trim();
  if (/^https?:\/\//i.test(s)) s = path(s);
  s = s.replace(/^\/+|\/+$/g, '');
  if (!s || /^video(?:\/|$)/i.test(s) || /^(?:page|tag|author|wp-content|wp-admin|wp-json)$/i.test(s)) {
    fail('无效作品ID');
  }
  return s;
}

function anImg(u, base) {
