    if (!isNaN(n) && n > maxP) maxP = n;
  }
  return maxP;
}

function anBook(id) {
  var rid = anId(id);
  var r = get('/' + anSafeUri(rid) + '/');
  if (!own(r.url)) fail('图集发生跳转');
  var title = plain(text(r.body, 'h1.article-title, h1.entry-title, h1', r.url) || meta(r.body, 'og:title'));
  var imgs = anPageImgs(r.body, r.url);
  if (!title || !imgs.length) fail('没有取得相册图片');
  return { id: rid, title: title, cover: imgs[0], url: r.url };
}

