  filters: function () {
    return [group('category', '分类', BD_CATS)];
  },
  latest: function (page) {
    var p = bdPage(page);
    var start = (p - 1) * 20;
    return bdList(start > 0 ? '/?start=' + start : '/', p);
  },
  category: function (filters, page) {
    var p = bdPage(page);
    var cat = val(filters || {}, 'category', 'all');
    if (cat === 'all') return source.latest(p);
    if (!bdValidCat(cat)) fail('分类无效');
    var start = (p - 1) * 20;
    return bdList(start > 0 ? cat + '?start=' + start : cat, p);
  },
  search: function (keyword, page) {
    var p = bdPage(page);
    var kw = String(keyword || '').trim();
    if (!kw) return { items: [], hasMore: false };
    var start = (p - 1) * 20;
    var route = '/?search=' + enc(kw) + (start > 0 ? '&start=' + start : '');
    return bdList(route, p);
  },
  detail: function (id) {
    var book = bdBook(id);
    return { id: book.id, title: book.title, cover: book.cover };
  },
  chapters: function (id) {
    var book = bdBook(id);
    return slots([chapter(book.id, '完整相册', book.url, 0)]);
  },
  chapter: function (url) {
    var target = bdSafeUri(abs(url, env.baseUrl));
    if (!target || !own(target)) fail('章节地址无效');
    var first = get(target);
    if (!own(first.url)) fail('章节发生跳转');
    var imgs = bdPageImgs(first.body, first.url);
    var maxP = bdMaxPage(first.body, first.url);
    if (maxP > 125) maxP = 125;
    var baseClean = first.url.replace(/[?#].*$/, '');
    for (var p = 2; p <= maxP; p++) {
      var res = get(baseClean + '?page=' + p, first.url);
      if (!own(res.url)) break;
      var more = bdPageImgs(res.body, res.url);
      if (!more.length) break;
      for (var j = 0; j < more.length; j++) imgs.push(more[j]);
    }
    imgs = unique(imgs);
    if (!imgs.length) fail('没有取得相册图片');
    var title = bdCleanTitle(text(first.body, '.article-header h1, h1', first.url));
    return pageImages(first.url, imgs, title);
  }
};

