    var slug = String(post.slug);
    try { slug = decodeURIComponent(slug); } catch (e) {}
    slug = slug.replace(/^\/+|\/+$/g, '');
    if (!slug || seen[slug]) continue;
    var title = plain(post.title && post.title.rendered ? post.title.rendered : slug);
    if (!title) continue;
    var cover = '';
    var fm = post._embedded && post._embedded['wp:featuredmedia'];
    if (Array.isArray(fm) && fm.length && fm[0] && fm[0].source_url) {
