function hcGet(url, ref) {
  try {
    return get(url, ref);
  } catch (e) {
    if (/timed out|reset|closed|EOF/i.test(String(e))) return get(url, ref);
    throw e;
  }
}

function hcPageNum(p) {
  var n = Number(p || 1);
  return !isFinite(n) || n < 1 ? 1 : Math.floor(n);
}

function hcCleanTitle(t) {
  return plain(t).replace(/\s*[-–|]\s*Hentai Cosplay\s*$/i, '').trim();
}

function hcExtractTitle(r) {
  var t = hcCleanTitle(text(r.body, '#title h2, h2', r.url));
  if (!t || /^Hentai Cosplay$/i.test(t)) {
    t = hcCleanTitle(meta(r.body, 'og:title') || text(r.body, 'title', r.url));
  }
  return t;
}

function hcParseList(r, curPage) {
  var items = [];
  var cards = q(r.body, '.image-list-item', r.url);
  for (var i = 0; i < cards.length; i++) {
    var h = cards[i].html || '';
    var a = one(h, '.image-list-item-title a[href*="/image/"], .image-list-item-image a[href*="/image/"]', r.url);
    if (!a || !a.href) continue;
    var href = abs(a.href, r.url);
    if (!href || href.indexOf('/image/') < 0) continue;
    var title = plain(text(h, '.image-list-item-title a', r.url)) || plain(attr(h, 'img', 'alt', r.url));
    if (!title) continue;
    var im = one(h, 'img', r.url);
    var cov = im ? image(im) : '';
    if (cov && cov.indexOf('//') === 0) cov = 'https:' + cov;
    cov = cov ? abs(cov, r.url) : '';
    items.push(summary(path(href), title, cov, ''));
  }
  items = unique(items, function (it) { return it.id; });

  var hasMore = false;
  var pLinks = q(r.body, '#paginator a[href], .paginator a[href], .pager a[href], a[href*="/page/"]', r.url);
  for (var j = 0; j < pLinks.length; j++) {
    var ph = pLinks[j].href || '';
    var pt = plain(pLinks[j].text);
    var m = match(ph, /\/page\/(\d+)\//);
    var target = m ? Number(m) : 0;
    if (target > curPage || /下一页|下页|Next|»|>/.test(pt)) {
      hasMore = true;
      break;
    }
  }
  return { items: items, hasMore: hasMore };
}

function hcIsDirectUploadUrl(u) {
  return /^https?:\/\/[^/]*hentai-cosplays?(?:-xxx)?\.com\/upload\//i.test(u) || path(u).indexOf('/upload/') === 0;
}

function hcExtractPhotos(r) {
  var imgs = [];
  var links = q(r.body, '#display_image_detail a[data-modal-gallery-image-item], #display_image_detail a[href*="/upload/"]', r.url);
  for (var i = 0; i < links.length; i++) {
    var l = links[i];
    if (!l.href) continue;
    var u = l.href;
    if (u.indexOf('//') === 0) u = 'https:' + u;
    u = abs(u, r.url);
    if (u && hcIsDirectUploadUrl(u)) imgs.push(u);
  }
  if (!imgs.length) {
    var nodes = q(r.body, '#display_image_detail img[src*="/upload/"], #display_image_detail img[data-src*="/upload/"]', r.url);
    for (var j = 0; j < nodes.length; j++) {
      var u2 = image(nodes[j]);
      if (!u2) continue;
      if (u2.indexOf('//') === 0) u2 = 'https:' + u2;
      u2 = abs(u2.replace(/\/p=\d+(?:x\d+)?\//, '/'), r.url);
      if (u2 && hcIsDirectUploadUrl(u2)) imgs.push(u2);
    }
  }
  return unique(imgs, function (u) { return u; });
}

function hcPagedUrl(prefix, page) {
  var cleanPrefix = BASE + prefix.replace(/\/+$/, '');
  return page <= 1 ? cleanPrefix + '/' : cleanPrefix + '/page/' + page + '/';
}

var source = {
  filters: function () {
    return [group('category', '分类', HC_CAT_PAIRS)];
  },
  latest: function (page) {
    var p = hcPageNum(page);
    return hcParseList(hcGet(hcPagedUrl('/recently', p)), p);
  },
  category: function (selected, page) {
    var p = hcPageNum(page);
    var v = val(selected, 'category', 'all');
    if (!v || v === 'all') return source.latest(p);
    var prefix = v.indexOf('tag:') === 0 ? '/search/tag/' + enc(v.substring(4)) : '/' + v;
    return hcParseList(hcGet(hcPagedUrl(prefix, p)), p);
  },
  search: function (keyword, page) {
    var kw = plain(keyword || '');
    if (!kw) return { items: [], hasMore: false };
    var p = hcPageNum(page);
    return hcParseList(hcGet(hcPagedUrl('/search/keyword/' + enc(kw), p)), p);
  },
  detail: function (id) {
    var url = abs(id, BASE + '/');
    var r = hcGet(url);
    var title = hcExtractTitle(r);
    var imgs = hcExtractPhotos(r);
    var cov = imgs.length ? imgs[0] : abs(meta(r.body, 'og:image'), r.url);
    var tagLinks = q(r.body, '#detail_tag a', r.url);
    var tags = [];
    for (var i = 0; i < tagLinks.length; i++) {
      var t = plain(tagLinks[i].text);
      if (t && tags.indexOf(t) < 0 && tags.length < 12) tags.push(t);
    }
    return {
      id: String(id),
      title: title || String(id),
      cover: cov || '',
      status: '已完结',
      tags: tags,
      description: plain(meta(r.body, 'description'))
