  },
  chapters: function (id) {
    return slots([chapter(id, '完整相册', abs(id, BASE + '/'), 0)]);
  },
  chapter: function (url) {
    var albumUrl = abs(url, BASE + '/').split('#')[0];
    var stem = albumUrl.replace(/\/page\/\d+\/?$/, '').replace(/\/+$/, '');
    var r1 = hcGet(stem + '/');
    var title = hcExtractTitle(r1) || '完整相册';
    var photos = hcExtractPhotos(r1);
    var albumPath = path(stem).replace(/\/+$/, '');
    var maxPage = 1;
    var pLinks = q(r1.body, 'a[href*="/page/"]', r1.url);
    for (var i = 0; i < pLinks.length; i++) {
      var ph = pLinks[i].href || '';
      if (ph.indexOf(albumPath + '/page/') < 0) continue;
      var m = match(ph, /\/page\/(\d+)\//);
      if (m) {
        var n = Number(m);
        if (n > maxPage) maxPage = n;
      }
    }
    var cap = maxPage > 60 ? 60 : maxPage;
    for (var p = 2; p <= cap; p++) {
      var nextUrl = stem + '/page/' + p + '/';
      var rn = hcGet(nextUrl, stem + '/');
      var pImgs = hcExtractPhotos(rn);
      for (var j = 0; j < pImgs.length; j++) photos.push(pImgs[j]);
    }
    return pageImages(albumUrl, photos, title);
  }
};
